  'Task': 'Attività',
  'The task is on the date found. {summary} is the line it was in without the date, {line} the whole line, {time} its time (tasks have no time of their own, so it goes into the text), {title} the note\'s title': 'L’attività è alla data trovata. {summary} è la riga in cui si trovava senza la data, {line} la riga intera, {time} la sua ora (le attività non hanno un orario proprio, quindi va nel testo), {title} il titolo della nota',
  '{title} is the note\'s title, {date} today\'s date': '{title} è il titolo della nota, {date} la data di oggi',
  'Improve the title with the language model': 'Migliora il titolo con il modello linguistico',
  'Rewrites {summary} when the model from Settings is installed; otherwise it stays as it is': 'Riscrive {summary} quando il modello delle impostazioni è installato; altrimenti resta com’è',
  'Due: {when}': 'Scadenza: {when}',
  'Reads the pen writing of each page in the background and puts the text in a box under it. A page is read again only when its writing changes. Needs the handwriting model from Settings; a page takes a while on a tablet.': 'Legge la scrittura a penna di ogni pagina in background e mette il testo in una casella sotto. Una pagina viene riletta solo quando cambia la sua scrittura. Richiede il modello di scrittura a mano delle impostazioni; su un tablet una pagina richiede un po’ di tempo.',
  'A language model on this device reads the note and compares it with the notes in each folder; the note goes to the folder it resembles most, if that is clear enough. Needs the sentence model from Settings. The notes of a folder are read once, and again only when they change.': 'Un modello linguistico su questo dispositivo legge la nota e la confronta con le note di ogni cartella; la nota va nella cartella a cui somiglia di più, se è abbastanza chiaro. Richiede il modello di frasi delle impostazioni. Le note di una cartella vengono lette una volta, e di nuovo solo quando cambiano.',
