  'Also syncs your tasks with a CalDAV calendar and shows its events in the Calendar tab. Copies of notes are kept for 30 days.': 'Sincronizza anche le tue attività con un calendario CalDAV e mostra i suoi eventi nella scheda Calendario. Le copie delle note sono conservate per 30 giorni.',
