  'Leave': 'Esci',
  'Start a live session and send the link to whoever should join. Everything that is drawn or written shows up for everyone at once. What is sent is sealed with a key that only the link contains: nobody in between (not even the server that introduces your devices to each other) can read it. The session lasts as long as you keep this note open and the app running.': 'Avvia una sessione dal vivo e invia il link a chi deve partecipare. Tutto ciò che viene disegnato o scritto appare a tutti insieme. Ciò che viene inviato è sigillato con una chiave che solo il link contiene: nessuno lungo il percorso (nemmeno il server che presenta tra loro i tuoi dispositivi) può leggerlo. La sessione dura finché tieni aperta questa nota e l’app in funzione.',
