  'Advanced: server and relay': 'Avanzate: server e relay',
  'Platform look': 'Stile della piattaforma',
  'Automatic dresses the app like an iPhone app on an iPhone or iPad, and like a Material app elsewhere. Pick one to see it on any device.': 'Automatico dà all’app l’aspetto di un’app iPhone su iPhone o iPad, e quello di un’app Material altrove. Scegline uno per vederlo su qualsiasi dispositivo.',
  'Material': 'Material',
  'Colors the buttons, selections and markers in every part of the app.': 'Colora pulsanti, selezioni e indicatori in ogni parte dell’app.',
  'Button': 'Pulsante',
  'Chip': 'Chip',
  'Language model': 'Modello linguistico',
  'Titles for tasks from PDFs': 'Titoli delle attività dai PDF',
  'Record a meeting on the dashboard, or dictate into a note, and what is said is written down. It happens on this device (Whisper, MIT and Apache-2.0 licences); the sound is never sent away and not kept.': 'Registra una riunione dal pannello o detta in una nota: ciò che viene detto viene scritto. Avviene su questo dispositivo (Whisper, licenze MIT e Apache-2.0); l’audio non viene mai inviato altrove né conservato.',
  'Writes short titles for the tasks that automations make from dates in a PDF (Qwen3-0.6B, Apache-2.0 licence). It runs on this device and nothing is sent away; it is loaded only while it works. It needs a fair amount of memory while it does.': 'Scrive titoli brevi per le attività create dalle automazioni dalle date di un PDF (Qwen3-0.6B, licenza Apache-2.0). Gira su questo dispositivo e non viene inviato nulla altrove; viene caricato solo mentre lavora, e durante il lavoro richiede una buona quantità di memoria.',
  'Colors, borders and emoji for the calendar itself are set in the Calendar tab, with the palette button at the top.': 'I colori, i bordi e le emoji del calendario stesso si impostano nella scheda Calendario, con il pulsante tavolozza in alto.',
  'Original blue': 'Blu originale',
  '{description} It needs a model of about {size} MB.': '{description} Serve un modello di circa {size} MB.',
  'Model installed': 'Modello installato',
  'Model not installed': 'Modello non installato',
  'Download failed: {error}': 'Download non riuscito: {error}',
  'The server answers.': 'Il server risponde.',
  'Live collaboration': 'Collaborazione dal vivo',
  'Work on a note together with others at the same time. Everything is sealed with a key that only the invite link holds; the signalling server only introduces your devices to each other and sees nothing of the note (but it does see the addresses of the devices that connect, and when). You can use the one that comes with the app or run your own: the source has versions for Cloudflare Workers, Node and Dart in tool/signaling. Everyone in a session uses the server of whoever made the invite.': 'Lavora su una nota con altri nello stesso momento. Tutto è sigillato con una chiave che possiede solo il link d’invito; il server di segnalazione serve solo a presentare tra loro i dispositivi e non vede nulla della nota (ma vede gli indirizzi dei dispositivi che si connettono, e quando). Puoi usare quello incluso nell’app o eseguire il tuo: il codice sorgente ha versioni per Cloudflare Workers, Node e Dart in tool/signaling. Tutti in una sessione usano il server di chi ha fatto l’invito.',
  'Built-in server': 'Server integrato',
  'My own server': 'Il mio server',
  'Test and use': 'Prova e usa',
  'Using the built-in server.': 'Uso del server integrato.',
  'Your name in sessions': 'Il tuo nome nelle sessioni',
  'Note files': 'File di nota',
  'A note can be saved as one file (.uninote, a ZIP with the text, the strokes, pictures and the PDF) to keep, send, or open on another device: use "Save this note as a file" in the note, or the menu of a note. To have a file made by itself whenever a note was changed (into a folder that a sync program watches, say), add the automation "Save the note as a file" in the Automations tab.': 'Una nota può essere salvata in un unico file (.uninote, uno ZIP con testo, tratti, immagini e PDF) per conservarla, inviarla o aprirla su un altro dispositivo: usa «Salva questa nota come file» nella nota, o il menu di una nota. Per far creare un file automaticamente ogni volta che una nota viene modificata (in una cartella controllata da un programma di sincronizzazione, per esempio), aggiungi l’automazione «Salva la nota come file» nella scheda Automazioni.',
  'Open a note file...': 'Apri un file di nota...',
  'Sorting notes': 'Ordinamento delle note',
  'Sentence model': 'Modello di frasi',
  'Reads the meaning of a note with a small language model (a sentence transformer, Apache-2.0 licence). It files notes by the automation "Move the note to the folder it fits best", finds the passages that answer a question across all notes, and makes the graph follow the meaning. It runs on this device; nothing is sent away.': 'Legge il significato di una nota con un piccolo modello linguistico (un transformer di frasi, licenza Apache-2.0). Ordina le note con l’automazione «Sposta la nota nella cartella che le si addice di più», trova i passaggi che rispondono a una domanda in tutte le note e fa seguire il significato al grafo. Gira su questo dispositivo; non viene inviato nulla altrove.',
  'The automation "Move the note to the folder it fits best" reads the words of a note with a small language model (a sentence transformer, Apache-2.0 licence) and files it with the notes it resembles. It runs on this device; nothing is sent away.': 'L’automazione «Sposta la nota nella cartella che le si addice di più» legge le parole di una nota con un piccolo modello linguistico (un transformer di frasi, licenza Apache-2.0) e la archivia con le note a cui somiglia. Gira su questo dispositivo; non viene inviato nulla altrove.',
  'Handwriting': 'Scrittura a mano',
  'Select drawings with the lasso and choose "Convert handwriting to text". Reading happens on this device; nothing is sent away.': 'Seleziona disegni con il lazo e scegli «Converti scrittura in testo». La lettura avviene su questo dispositivo; non viene inviato nulla altrove.',
  'Which model reads the handwriting': 'Quale modello legge la scrittura',
  'GLM-OCR (MIT licence) reads each line of your writing as a picture, with the knowledge of a language model about which words are likely: far better than the others on German and English notes. About 800 MB to download and two to three gigabytes of memory while it reads; it may correct a word to English or write maths as LaTeX.': 'GLM-OCR (licenza MIT) legge ogni riga della tua scrittura come un’immagine, con la conoscenza di un modello linguistico su quali parole sono probabili: di gran lunga migliore degli altri su note in tedesco e inglese. Circa 800 MB da scaricare e da due a tre GB di memoria durante la lettura; può correggere una parola in inglese o scrivere la matematica in LaTeX.',
  'How carefully it looks': 'Accuratezza della lettura',
  'Quick': 'Rapida',
  'Quick takes about two thirds of the time and reads a little less exactly. Light takes less than half of it and reads clearly less exactly: for a slow device.': 'Rapida richiede circa due terzi del tempo e legge un po’ meno accuratamente. Leggera richiede meno della metà e legge chiaramente meno accuratamente: per un dispositivo lento.',
  'PaddleOCR-VL (Apache 2.0 licence) is a much bigger model: about 900 MB to download, a gigabyte or two of memory while it reads, and slow on a tablet. It reads each line of your writing as a picture, with the knowledge of a language model about which words are likely.': 'PaddleOCR-VL (licenza Apache 2.0) è un modello molto più grande: circa 900 MB da scaricare, uno o due GB di memoria durante la lettura, e lento su un tablet. Legge ogni riga della tua scrittura come un’immagine, con la conoscenza di un modello linguistico su quali parole sono probabili.',
  'Formulas': 'Formule',
  'Select a handwritten formula with the lasso and choose "Convert a handwritten formula to LaTeX". Reading happens on this device; nothing is sent away.': 'Seleziona una formula scritta a mano con il lazo e scegli «Converti una formula scritta a mano in LaTeX». La lettura avviene su questo dispositivo; non viene inviato nulla altrove.',
  'Which model reads the formulas': 'Quale modello legge le formule',
  'TexTeller (Apache 2.0 licence) reads handwriting far better, but is bigger and slower. It suits a computer or a fast tablet.': 'TexTeller (licenza Apache 2.0) legge la scrittura a mano molto meglio, ma è più grande e più lento. Adatto a un computer o a un tablet veloce.',
  'Pix2Text (MIT licence) is lighter and quicker, but made for printed formulas and poor at handwriting. Use it if the device is slow or short of memory.': 'Pix2Text (licenza MIT) è più leggero e veloce, ma pensato per formule stampate e scarso con la scrittura a mano. Usalo se il dispositivo è lento o a corto di memoria.',
  'AI assistant': 'Assistente IA',
  'Highlight text and choose "Summarize" (more than two words), "Tell me more" or "Ask a question"; the sparkle button in a note opens an assistant that answers questions about the whole document. Who answers is up to you; the text you highlight goes to that provider only.': 'Evidenzia del testo e scegli «Riassumi» (più di due parole), «Dimmi di più» o «Fai una domanda»; il pulsante a stella di una nota apre un assistente che risponde alle domande su tutto il documento. Chi risponde lo decidi tu; il testo evidenziato va solo a quel fornitore.',
  'Prompt for "Summarize"': 'Istruzione per «Riassumi»',
  'Standing instructions': 'Istruzioni permanenti',
  'Request': 'Richiesta',
  '{text} is the highlighted text, {length} how long the summary should be': '{text} è il testo evidenziato, {length} quanto deve essere lungo il riassunto',
  'Length': 'Lunghezza',
  'Back to the standard prompt': 'Torna all’istruzione standard',
  'Found on this computer. Needs {needs}.': 'Trovato su questo computer. Richiede {needs}.',
  'Needs {needs}.': 'Richiede {needs}.',
  'The download failed: {why}': 'Download non riuscito: {why}',
  'No graphics card runtime downloaded yet. Pick one above; it is used from the next start of the app.': 'Nessun runtime per la scheda grafica è ancora scaricato. Scegline uno sopra; verrà usato dal prossimo avvio dell’app.',
  'NVIDIA graphics card (CUDA 13)': 'Scheda grafica NVIDIA (CUDA 13)',
  'NVIDIA graphics card (CUDA 12)': 'Scheda grafica NVIDIA (CUDA 12)',
  'AMD graphics card (ROCm)': 'Scheda grafica AMD (ROCm)',
  'Intel graphics card / NPU (OpenVINO)': 'Scheda grafica Intel / NPU (OpenVINO)',
  'the NVIDIA driver 580 or newer, and CUDA 13 with cuDNN': 'il driver NVIDIA 580 o successivo, e CUDA 13 con cuDNN',
  'the NVIDIA driver, and CUDA 12 with cuDNN': 'il driver NVIDIA, e CUDA 12 con cuDNN',
  'ROCm 7.1': 'ROCm 7.1',
  'the Intel compute runtime': 'il runtime di calcolo Intel',
  'This computer has a graphics card ({names}), but the app is running on the runtime for the processor. Download the runtime for it below, then start the app again.': 'Questo computer ha una scheda grafica ({names}), ma l’app gira sul runtime per il processore. Scarica qui sotto quello giusto, poi riavvia l’app.',
  'Show extra small models': 'Mostra i modelli extra piccoli',
