  '{text} is the highlighted text, {question} what you ask': '{text} è il testo evidenziato, {question} la tua domanda',
  'Prompt for the document assistant': 'Istruzione per l’assistente del documento',
  '{text} is the passages of the document found for the question, {question} what you ask': '{text} sono i passaggi del documento trovati per la domanda, {question} la tua domanda',
  'Model': 'Modello',
