  'Address': 'Indirizzo',
  'e.g. https://api.openai.com/v1 or http://localhost:11434/v1': 'ad es. https://api.openai.com/v1 o http://localhost:11434/v1',
  'e.g. gpt-4o-mini or llama3.2': 'ad es. gpt-4o-mini o llama3.2',
  'API key': 'Chiave API',
  'A key is saved in this device\'s keystore; leave empty to keep it. Servers on your own machine often need none.': 'Una chiave è salvata nel portachiavi di questo dispositivo; lascia vuoto per conservarla. I server sulla tua macchina spesso non ne hanno bisogno.',
  'Kept in this device\'s keystore. Servers on your own machine often need none.': 'Conservata nel portachiavi di questo dispositivo. I server sulla tua macchina spesso non ne hanno bisogno.',
  'Trying...': 'Prova in corso...',
  'Save and try': 'Salva e prova',
  'Delete the key': 'Elimina la chiave',
  'AI features': 'Funzioni IA',
  'On': 'Attive',
  'Off: nothing in the app uses AI': 'Disattive: nulla nell’app usa l’IA',
  'Turn this off and every AI feature goes away at once: the assistant, summaries and questions about highlighted text, smart task titles, reading handwriting and formulas. Nothing is run, and nothing is sent to an AI service. Your downloads and settings below stay as they are.': 'Disattivandole, tutte le funzioni IA spariscono in una volta: l’assistente, i riassunti e le domande sul testo evidenziato, i titoli intelligenti delle attività, la lettura della scrittura a mano e delle formule. Non viene eseguito nulla e nulla viene inviato a un servizio IA. I download e le impostazioni qui sotto restano come sono.',
  'Language': 'Lingua',
  'The language of the menus and messages. By default the language of the device is used.': 'La lingua dei menu e dei messaggi. Di default si usa la lingua del dispositivo.',
  'Device language': 'Lingua del dispositivo',
