  'This link does not use a secure address.': 'Questo link non usa un indirizzo sicuro.',
  'This shared copy is gone: it expired or was taken down.': 'Questa copia condivisa non c’è più: è scaduta o è stata rimossa.',
  'The shared copy could not be downloaded ({code}).': 'La copia condivisa non è stata scaricata ({code}).',
  'This shared copy is too big.': 'Questa copia condivisa è troppo grande.',
  'This calendar is too big.': 'Questo calendario è troppo grande.',
  'This copy cannot be opened: the link is incomplete, or the file was changed.': 'Questa copia non può essere aperta: il link è incompleto o il file è stato modificato.',
  'Puts a sealed copy of this note on {service} and makes a link to it. Whoever opens the link gets their own copy, even while you are offline. Only the link can open the copy; {service} sees a file it cannot read. The link works for {days} days.': 'Mette una copia sigillata di questa nota su {service} e crea un link. Chi apre il link ottiene una propria copia, anche quando sei offline. Solo il link può aprire la copia; {service} vede un file che non può leggere. Il link funziona per {days} giorni.',
  'Connect {service} first.': 'Collega prima {service}.',
