  'The service answered with an error ({code}).': 'Il servizio ha risposto con un errore ({code}).',
  'Fill in every field.': 'Compila tutti i campi.',
  'The file was stored but cannot be downloaded through a signed link ({code}). Is the region right?': 'Il file è stato salvato ma non può essere scaricato tramite un link firmato ({code}). La regione è giusta?',
  'Sharing copies of notes': 'Condivisione di copie di note',
  'A copy of a note can be put on a storage service you have an account with, and opened by anyone with the link, also while you are offline. The copy is sealed with a key that is only in the link: the service stores a file it cannot read. Several services can be set up; the one chosen when you share is used.': 'Una copia di una nota può essere messa su un servizio di archiviazione per cui hai un account, e aperta da chiunque abbia il link, anche offline. La copia è sigillata con una chiave che è solo nel link: il servizio conserva un file che non può leggere. Si possono configurare più servizi; viene usato quello scelto al momento della condivisione.',
  'The address must start with https://': 'L’indirizzo deve iniziare con https://',
  'It works. Copies can be shared through this bucket.': 'Funziona. Le copie possono essere condivise tramite questo bucket.',
  'Any S3-compatible service: Cloudflare R2, Backblaze B2, Wasabi, MinIO, Amazon S3. Make an access key that may read and write in one bucket. Links work for 7 days; the copies are deleted from the bucket after that, the next time you share.': 'Qualsiasi servizio compatibile con S3: Cloudflare R2, Backblaze B2, Wasabi, MinIO, Amazon S3. Crea una chiave di accesso che possa leggere e scrivere in un solo bucket. I link funzionano per 7 giorni; dopodiché le copie vengono eliminate dal bucket alla prossima condivisione.',
  'Bucket {bucket} at {host}': 'Bucket {bucket} su {host}',
