  'The browser could not be opened.': 'Impossibile aprire il browser.',
  'Copies are put in a folder of the app on your {service}, and the link works for {days} days; the copies are deleted from it after that, the next time you share.': 'Le copie vengono salvate in una cartella dell’app sul tuo {service}, e il link funziona per {days} giorni; dopodiché le copie vengono eliminate, alla prossima condivisione.',
  'Sign in to {service}': 'Accedi a {service}',
