  'Dropbox needs an app of your own: create one at dropbox.com/developers/apps ("Scoped access", "App folder"), allow files.content.write and sharing.write, add the redirect URI notation://oauth/dropbox, and enter its app key here.': 'Dropbox richiede un’app propria: creala su dropbox.com/developers/apps («Scoped access», «App folder»), consenti files.content.write e sharing.write, aggiungi l’URI di reindirizzamento notation://oauth/dropbox e inserisci qui la sua chiave dell’app.',
  'OneDrive needs an app of your own: register one in the Azure portal (App registrations, accounts of any kind), add the redirect URI notation://oauth/onedrive for "Mobile and desktop", allow Files.ReadWrite.AppFolder and offline_access, and enter its application ID here.': 'OneDrive richiede un’app propria: registrala nel portale Azure (App registrations, account di qualsiasi tipo), aggiungi l’URI di reindirizzamento notation://oauth/onedrive per «Mobile and desktop», consenti Files.ReadWrite.AppFolder e offline_access, e inserisci qui il suo ID applicazione.',
