  'Paste from text': 'Incolla da testo',
  'Change a number first: a copy with the same numbers is the same brush.': 'Cambia prima un numero: una copia con gli stessi numeri è lo stesso pennello.',
  'Saved "{name}" as a brush of its own.': '«{name}» salvato come pennello a sé.',
  'Copied the brush "{name}" as text. Paste it in the designer on another device.': 'Il pennello «{name}» è stato copiato come testo. Incollalo nel progettista su un altro dispositivo.',
  'Took in the brush "{name}"; it is in the brush menu.': 'Il pennello «{name}» è stato accolto; si trova nel menu dei pennelli.',
  'A mixed brush is made of two brushes that are not mixes themselves.': 'Un pennello misto è fatto di due pennelli che non sono a loro volta miscele.',
  'This is too long to be a brush.': 'Questo è troppo lungo per essere un pennello.',
  'This is not a brush (the text is not a brush code).': 'Questo non è un pennello (il testo non è un codice di pennello).',
