  'This is not a brush.': 'Questo non è un pennello.',
  'Some lines of this note are drawn with a brush of the extension {names}, which is not installed or is switched off. They are drawn with the pen.': 'Alcune linee di questa nota sono disegnate con un pennello dell’estensione {names}, che non è installata o è disattivata. Sono disegnate con la penna.',
