  'Pen': 'Penna',
  'Roller': 'Rullo',
  'Drawing tools of extensions': 'Strumenti di disegno delle estensioni',
  'Drawing tool: {tool}': 'Strumento di disegno: {tool}',
  'Plain pen': 'Penna semplice',
  'Draw on the pages with the drawing tools it lists': 'Disegna sulle pagine con gli strumenti di disegno che elenca',
  'A paint roller for the drawing bar: a wide band with streaks.': 'Un rullo da pittura per la barra del disegno: una fascia larga con striature.',
  'Import a PDF to write on, and export a note as a PDF.': 'Importa un PDF su cui scrivere ed esporta una nota come PDF.',
  'Languages': 'Lingue',
  'Lasso': 'Lazo',
  'Law, business, economics and social sciences': 'Diritto, economia, management e scienze sociali',
  'Lines drawn nearly straight are straightened, and drawings very close to a rectangle, ellipse, triangle or diamond become that shape.': 'Le linee disegnate quasi dritte vengono raddrizzate, e i disegni molto vicini a un rettangolo, un’ellisse, un triangolo o un rombo diventano quella forma.',
  'Lines, arrows, rectangles and ellipses drawn with the pen.': 'Linee, frecce, rettangoli ed ellissi disegnati con la penna.',
  'Live sessions and shared copies of notes with other people.': 'Sessioni dal vivo e copie condivise di note con altre persone.',
  'Look things up': 'Cerca informazioni',
  'Made for you now and kept. If two people with the same name work together, it tells them apart. It is not a password.': 'Creato per te ora e conservato. Se due persone con lo stesso nome lavorano insieme, lo distingue. Non è una password.',
  'Made for you the first time the app started and kept. It tells two people with the same name apart when you work on a note together. It is not a password.': 'Creato per te la prima volta che l’app si è avviata, e conservato. Distingue due persone con lo stesso nome quando lavorate insieme a una nota. Non è una password.',
  'Make flashcards from a document with the assistant, and learn them. Needs the assistant.': 'Crea schede di studio da un documento con l’assistente, e studiale. Richiede l’assistente.',
  'Mathematics and physics': 'Matematica e fisica',
  'Maths': 'Matematica',
  'Next': 'Avanti',
  'Notes you write and draw, PDFs you annotate, and notes you work on together with others.': 'Note che scrivi e disegni, PDF che annoti e note su cui lavori insieme ad altri.',
  'Only the basics': 'Solo le basi',
  'Organising and sharing': 'Organizzazione e condivisione',
  'Other people see this name when you work on a note together, and it goes on what you add to a note, so the history can show who wrote what.': 'Gli altri vedono questo nome quando lavorate insieme a una nota, e compare su ciò che aggiungi a una nota, così la cronologia può mostrare chi ha scritto cosa.',
  'PDF': 'PDF',
  'Philosophy, history and literature': 'Filosofia, storia e letteratura',
  'Pictures': 'Immagini',
  'Plots': 'Grafici',
  'Put pictures on a page.': 'Metti immagini su una pagina.',
  'Reading and looking things up': 'Leggere e cercare informazioni',
  'Reading texts closely, quoting and arguing in writing.': 'Leggere testi con attenzione, citare e argomentare per iscritto.',
  'Rules that sort, title and file notes by themselves.': 'Regole che ordinano, intitolano e archiviano le note da sole.',
  'Save a note as a file (.uninote) and open one.': 'Salva una nota come file (.uninote) e aprine una.',
  'Search the web, Wikipedia and translate from selected text, with the page beside the note.': 'Cerca sul web, Wikipedia e traduci dal testo selezionato, con la pagina accanto alla nota.',
  'Select, move, copy and delete drawings, text boxes and pictures by drawing around them.': 'Seleziona, sposta, copia ed elimina disegni, caselle di testo e immagini disegnando attorno a essi.',
  'Set up for what you use the app for:': 'Impostazione in base a ciò per cui usi l’app:',
  'Shapes': 'Forme',
  'Sharing notes and writing them together.': 'Condividere note e scriverle insieme.',
  'Show everything': 'Mostra tutto',
  'Show me everything': 'Mostrami tutto',
  'Show the intro again': 'Mostra di nuovo l’introduzione',
  'Sketches, pictures and layouts.': 'Schizzi, immagini e impaginazioni.',
  'Skip': 'Salta',
  'Every tool is on.': 'Tutti gli strumenti sono attivi.',
  'Nothing chosen: you start with the basics. More tools can be switched on in the settings at any time.': 'Nulla di scelto: inizi con l’essenziale. Altri strumenti si possono attivare nelle impostazioni in qualsiasi momento.',
  'Everyday notes and meetings': 'Note di tutti i giorni e riunioni',
  'Lists, meeting notes, to-dos and things to remember.': 'Elenchi, appunti di riunioni, cose da fare e da ricordare.',
  'Everyday': 'Quotidiano',
  'Straight lines and shapes': 'Linee dritte e forme',
  'Switch off what you do not use and it goes away from the screens. Nothing is deleted: notes that use a tool that is off stay as they are.': 'Disattiva ciò che non usi e sparisce dagli schermi. Non si cancella nulla: le note che usano uno strumento disattivato restano come sono.',
  'Tables': 'Tabelle',
  'Tables in text boxes and in the written document.': 'Tabelle nelle caselle di testo e nel documento scritto.',
  'The calendar, the week view, tasks and syncing them.': 'Il calendario, la vista settimana, le attività e la loro sincronizzazione.',
  'The name other people see in live sessions, on what you add to a note, and in the history of a note.': 'Il nome che gli altri vedono nelle sessioni dal vivo, su ciò che aggiungi a una nota e nella cronologia di una nota.',
  'Their id: {id}': 'Il suo id: {id}',
  'Theme images': 'Immagini del tema',
  'Three quick questions make it fit you: what to call you, what you use it for, and which tools you want to see. You can change all of it later in the settings.': 'Tre domande rapide per adattarla a te: come chiamarti, a cosa la usi e quali strumenti vuoi vedere. Puoi cambiare tutto più tardi nelle impostazioni.',
  'Tools': 'Strumenti',
  'Turn a handwritten formula into LaTeX (needs the model from the settings).': 'Converte una formula scritta a mano in LaTeX (richiede il modello nelle impostazioni).',
  'Turn handwriting into text (needs the model from the settings).': 'Converte la scrittura a mano in testo (richiede il modello nelle impostazioni).',
  'Unnamed': 'Senza nome',
  'Vocabulary, grammar and texts in more than one language.': 'Vocabolario, grammatica e testi in più lingue.',
  'Welcome to Notation': 'Benvenuto in Notation',
  'What should we call you?': 'Come dobbiamo chiamarti?',
  'What will you use Notation for?': 'Per cosa userai Notation?',
  'Working together': 'Lavoro di gruppo',
  'Working with others': 'Lavorare con altri',
  'Writing and drawing': 'Scrivere e disegnare',
  'Creative tools': 'Strumenti creativi',
  'More brushes': 'Altri pennelli',
  'Pencil, fountain pen, calligraphy nib, marker, charcoal, airbrush and watercolour for the drawing bar.': 'Matita, penna stilografica, pennino da calligrafia, pennarello, carboncino, aerografo e acquerello per la barra del disegno.',
  'Symmetry drawing': 'Disegno con simmetria',
  'Draw with a mirror or around a centre: what you draw is repeated on the other side or in turns (mandalas, patterns).': 'Disegna con uno specchio o attorno a un centro: ciò che disegni si ripete dall’altra parte o a giri (mandala, motivi).',
  'Line stabiliser': 'Stabilizzatore di linea',
  'Smooths a shaky hand: the line follows the pen with a little delay, for clean lettering and line art.': 'Smussa una mano tremolante: la linea segue la penna con un leggero ritardo, per lettering e disegno a linee pulite.',
  'Pencil': 'Matita',
  'Fountain pen': 'Stilografica',
  'Calligraphy': 'Calligrafia',
  'Marker': 'Pennarello',
  'Charcoal': 'Carboncino',
  'Airbrush': 'Aerografo',
  'Watercolour': 'Acquerello',
  'Line stabiliser: {level}': 'Stabilizzatore di linea: {level}',
  'Off': 'Disattivato',
  'Light': 'Leggero',
  'Medium': 'Medio',
  'Strong': 'Forte',
  'Symmetry: {kind}': 'Simmetria: {kind}',
  'Mirror left and right': 'Specchio sinistra e destra',
  'Mirror up and down': 'Specchio sopra e sotto',
  'Mirror both ways': 'Specchio in entrambe le direzioni',
  'Around the centre': 'Attorno al centro',
  'Around the centre, mirrored': 'Attorno al centro, specchiato',
  '{n} turns': '{n} giri',
  'You': 'Tu',
  'You can leave the name empty and set it later.': 'Puoi lasciare il nome vuoto e impostarlo più tardi.',
  'Your id: {id}': 'Il tuo id: {id}',
  'Your name': 'Il tuo nome',
  'Your tools': 'I tuoi strumenti',
  'Smart features': 'Funzioni intelligenti',
  'Everything on these pages was made by the app. Write on it, change it, delete it: it is only here to try things on.': 'Tutto ciò che c’è in queste pagine è stato creato dall’app. Scrivi, modifica o elimina: serve solo per provare.',
  'Everything in this note was made by the app. Write on it, change it, delete it: it is only here to try things on.': 'Tutto ciò che c’è in questa nota è stato creato dall’app. Scrivi, modifica o elimina: serve solo per provare.',
  'Write like a document': 'Scrivere come un documento',
  'This page is a written document: **bold**, *italic*, `code` and ==highlights== are just Markdown, and the bar at the side formats the text for you. Headings, the table of contents above, tables, pictures and footnotes[^1] all work, and it prints as pages.': 'Questa pagina è un documento scritto: **grassetto**, *corsivo*, `codice` e ==evidenziati== sono Markdown, e la barra laterale formatta il testo per te. Titoli, sommario qui sopra, tabelle, immagini e note a piè di pagina[^1] funzionano, e si stampa a pagine.',
  'Pick the pen in the drawing bar and write anywhere, with a stylus or a finger. Draw a ring round something with the lasso to move, copy or delete it. A note can hold both: the written document first, then pages to draw on.': 'Scegli la penna nella barra del disegno e scrivi ovunque, con uno stilo o con un dito. Disegna un cerchio attorno a qualcosa con il lazo per spostarlo, copiarlo o eliminarlo. Una nota può contenere entrambi: prima il documento scritto, poi le pagine su cui disegnare.',
  'A mind map, a state machine, a search tree and a graph with its shortest ways: drawn from text, on the next page. The facts under each were worked out by the app.': 'Una mappa mentale, una macchina a stati, un albero di ricerca e un grafo con i suoi percorsi più brevi: disegnati dal testo, nella pagina successiva. I dati sotto ciascuno sono stati ricavati dall’app.',
  'Like this one. The next page is a notebook page: draw on it.': 'Come questa. La pagina successiva è una pagina di quaderno: disegnaci sopra.',
  'Write and draw': 'Scrivere e disegnare',
  'Pen and highlighter': 'Penna ed evidenziatore',
  'Lasso and layers': 'Lazo e livelli',
  'Check my working': 'Controlla i miei calcoli',
  'Solve and plot': 'Risolvi e traccia',
  'Diagrams': 'Diagrammi',
  'Mind maps': 'Mappe mentali',
  'Automata, trees, graphs': 'Automi, alberi, grafi',
  'Together': 'Insieme',
  'Live sessions': 'Sessioni dal vivo',
  'A mind map, made from a list with the diagram button.': 'Una mappa mentale, fatta da un elenco con il pulsante diagramma.',
  'Pick the pen in the drawing bar and write anywhere, with a stylus or a finger. Draw a ring round something with the lasso to move, copy or delete it. Double-tap the page (triple-click on a computer) to add a text box like this one.': 'Scegli la penna nella barra del disegno e scrivi ovunque, con uno stilo o con un dito. Disegna un cerchio attorno a qualcosa con il lazo per spostarlo, copiarlo o eliminarlo. Fai doppio tocco sulla pagina (triplo clic su un computer) per aggiungere una casella di testo come questa.',
  'Write a worked solution by hand. A moment later each line gets a green check or a red cross; tap it to see what was checked. Like this:': 'Scrivi a mano una soluzione svolta. Poco dopo ogni riga riceve un segno di spunta verde o una croce rossa; toccalo per vedere cosa è stato controllato. Così:',
  'End a calculation with = and the result appears:': 'Chiudi un calcolo con = e compare il risultato:',
  'true in every row': 'vero in ogni riga',
  'false in every row': 'falso in ogni riga',
  'true in {n} of {rows} rows': 'vero in {n} righe su {rows}',
  'Truth tables': 'Tabelle di verità',
  'The grid button makes the truth table of a formula, with a column for every part of it. This is (p ∧ q) → r:': 'Il pulsante griglia crea la tabella di verità di una formula, con una colonna per ogni sua parte. Questa è (p ∧ q) → r:',
  'Diagrams from a few lines of text': 'Diagrammi da poche righe di testo',
  'A state machine, a search tree and a graph with its shortest ways, drawn from text. The facts under each were worked out by the app.': 'Una macchina a stati, un albero di ricerca e un grafo con i suoi percorsi più brevi, disegnati dal testo. I dati sotto ciascuno sono stati ricavati dall’app.',
  'Flashcards from your notes and your mistakes': 'Schede di studio dalle tue note e dai tuoi errori',
  'Citations with [@key] and a list of sources': 'Citazioni con [@chiave] e un elenco delle fonti',
  'PDFs to write on, and notes as PDF': 'PDF su cui scrivere, e note come PDF',
  'A calendar and tasks': 'Un calendario e attività',
  'Notes written together, live': 'Note scritte insieme, dal vivo',
  'And more': 'E altro ancora',
  'The settings hold the tools you can switch on and off, the models to download and the switch for all the AI features.': 'Le impostazioni contengono gli strumenti che puoi attivare o disattivare, i modelli da scaricare e l’interruttore di tutte le funzioni IA.',
  'Language, colour and pen': 'Lingua, colore e penna',
  'All of this can be changed later in the settings.': 'Tutto questo si può cambiare più tardi nelle impostazioni.',
  'Try your pen': 'Prova la tua penna',
  'Write or draw in the box with the pen, a finger or the mouse.': 'Scrivi o disegna nel riquadro con la penna, un dito o il mouse.',
  'What a finger does': 'Cosa fa un dito',
  'A pen was found, and it tells how hard it presses.': 'È stata rilevata una penna, e indica quanta pressione esercita.',
  'A pen was found.': 'È stata rilevata una penna.',
  'A finger was found. If you have a pen, try it too.': 'È stato rilevato un dito. Se hai una penna, provala anche.',
  'A mouse was found.': 'È stato rilevato un mouse.',
  'Where your notes live': 'Dove vivono le tue note',
  'Your notes are kept on this device, in the app. Nothing is sent anywhere unless you set it up.': 'Le tue note sono conservate su questo dispositivo, nell’app. Non viene inviato nulla altrove, a meno che tu non lo configuri.',
  'Use it on more than one device?': 'Lo usi su più dispositivi?',
  'Link this device with your others to keep the notes, folders and settings the same on all of them.': 'Collega questo dispositivo agli altri per mantenere uguali note, cartelle e impostazioni su tutti.',
  'Set up syncing': 'Configura la sincronizzazione',
  'Syncing': 'Sincronizzazione',
  'Not now is fine: it is in the settings whenever you want it.': '«Non ora» va bene: è nelle impostazioni quando vuoi.',
  'The download of "{name}" did not work. You can try again in the settings.': 'Il download di «{name}» non è riuscito. Puoi riprovare nelle impostazioni.',
  'You can carry on: the download continues in the background.': 'Puoi continuare: il download prosegue in background.',
  '**Welcome to Notation**\nThis page shows what you can do. You can write on it, change it or delete it: it is only here to try things on.': '**Benvenuto in Notation**\nQuesta pagina mostra cosa puoi fare. Puoi scriverci sopra, modificarla o eliminarla: serve solo per provare.',
  '**Write and draw**\nPick the pen in the drawing bar and write anywhere on the page, with a stylus or a finger. Draw a ring round something with the lasso to move, copy or delete it. Double-tap the page (triple-click on a computer) to add a text box like this one.': '**Scrivere e disegnare**\nScegli la penna nella barra del disegno e scrivi ovunque sulla pagina, con uno stilo o con un dito. Disegna un cerchio attorno a qualcosa con il lazo per spostarlo, copiarlo o eliminarlo. Fai doppio tocco sulla pagina (triplo clic su un computer) per aggiungere una casella di testo come questa.',
  '**Tables and truth tables**\nThe table button in the insert bar makes a table. The grid button next to it makes the truth table of a formula, like this one for p → q:': '**Tabelle e tabelle di verità**\nIl pulsante tabella nella barra di inserimento crea una tabella. Il pulsante griglia accanto crea la tabella di verità di una formula, come questa per p → q:',
  '**Mind maps and diagrams**\nThe diagram button turns an outline, or lines such as Start -> Check -> Done, into a mind map or a flowchart. In advanced mode it draws a state machine, a tree or a graph from a text and tells you what is true about it.': '**Mappe mentali e diagrammi**\nIl pulsante diagramma trasforma una scaletta, o righe come Inizio -> Controlla -> Fatto, in una mappa mentale o in un diagramma di flusso. In modalità avanzata disegna da un testo una macchina a stati, un albero o un grafo e ti dice cosa è vero su di esso.',
  '**Maths**\nWrite a calculation by hand and end it with = to see the result. With "Check my maths" on, each line of a worked solution gets a green check or a red cross a moment after you write it; tap the mark to see what was checked and to correct what was read. This needs the formula model from the settings.': '**Matematica**\nScrivi un calcolo a mano e chiudilo con = per vedere il risultato. Con «Controlla i miei calcoli» attivo, ogni riga di una soluzione svolta riceve un segno di spunta verde o una croce rossa poco dopo averla scritta; tocca il segno per vedere cosa è stato controllato e correggere ciò che è stato letto male. Serve il modello di formule delle impostazioni.',
  '**Handwriting to text**\nSelect some handwriting to turn it into text. This needs the handwriting model from the settings.': '**Scrittura a mano in testo**\nSeleziona della scrittura a mano per convertirla in testo. Serve il modello di scrittura a mano delle impostazioni.',
  '**Where to go from here**\nThe settings hold the tools you can switch on and off, the models to download and the switch for all the AI features. Every tool in the bar has a tip when you hold the pointer over it or press and hold.': '**E poi?**\nLe impostazioni contengono gli strumenti che puoi attivare o disattivare, i modelli da scaricare e l’interruttore di tutte le funzioni IA. Ogni strumento della barra ha un suggerimento quando tieni il puntatore sopra o premi a lungo.',
  'Make a note that shows the tools': 'Crea una nota che mostra gli strumenti',
  'One page, with the tools you chose on it, to try them on. You can delete it.': 'Una pagina, con gli strumenti che hai scelto, per provarli. Puoi eliminarla.',
  'Reading your handwriting, checking your maths and the assistant run on this device. Each needs a model that is downloaded once.': 'La lettura della tua scrittura, il controllo dei calcoli e l’assistente girano su questo dispositivo. Ciascuno richiede un modello scaricato una volta sola.',
  'Turn this off and no AI feature is offered and nothing is downloaded. You can turn it on later in the settings.': 'Disattivandolo, nessuna funzione IA viene proposta e non si scarica nulla. Puoi riattivarlo più tardi nelle impostazioni.',
  'Already on this device': 'Già su questo dispositivo',
  '{description} About {size} MB.': '{description} Circa {size} MB.',
  'Nothing will be downloaded.': 'Non verrà scaricato nulla.',
  'Pressing Start downloads {size} MB in the background; the settings show how far it is.': 'Premendo Avvia si scaricano {size} MB in background; le impostazioni mostrano a che punto è.',
  'Turns what you write by hand into text, to search and copy.': 'Trasforma ciò che scrivi a mano in testo, da cercare e copiare.',
  'Formulas and maths check': 'Formule e controllo dei calcoli',
  'Reads handwritten formulas and marks your working line by line.': 'Legge le formule scritte a mano e controlla i tuoi calcoli riga per riga.',
  'Answers questions about a note and summarises it. A big download, so it is only on if you tick it.': 'Risponde a domande su una nota e la riassume. È un download grosso, quindi si attiva solo se lo spunti.',
  'Duplicate drawing': 'Duplica disegno',
  'Duplicate the selection': 'Duplica la selezione',
  'Duplicate text box': 'Duplica casella di testo',
  'Duplicate picture': 'Duplica immagine',
  'Read the writing and formulas ahead of time, so converting them is instant': 'Leggi in anticipo scrittura e formule, così convertirle è immediato',
  'Reads the handwriting ahead of time': 'Legge in anticipo la scrittura a mano',
  'Reads the formulas ahead of time': 'Legge in anticipo le formule',
  'Reads the handwriting and the formulas ahead of time': 'Legge in anticipo scrittura a mano e formule',
  'The handwriting and formula readers are switched off (see Settings)': 'I lettori di scrittura e formule sono disattivati (vedi impostazioni)',
  'The models are not installed (see Settings)': 'I modelli non sono installati (vedi impostazioni)',
  'Check my maths': 'Controlla i miei calcoli',
  'Marks the maths you write as right or wrong, line by line, a moment after you wrote it, and gives the result of a line that ends with =. Needs the formula model from the settings.': 'Segna i calcoli che scrivi come giusti o sbagliati, riga per riga, poco dopo averli scritti, e dà il risultato di una riga che termina con =. Serve il modello di formule delle impostazioni.',
  'This looks right': 'Sembra giusto',
  'Right, up to rounding': 'Giusto, a meno di arrotondamenti',
  'The sum does not work out': 'La somma non torna',
  'The two sides are not equal': 'I due membri non sono uguali',
  'That is not the derivative': 'Non è la derivata',
  'That is not the integral': 'Non è l’integrale',
  'That is not the limit': 'Non è il limite',
  'That does not solve the line above': 'Questo non risolve la riga sopra',
  'This does not follow from the line above': 'Questo non segue dalla riga sopra',
  'A solution of the line above is lost': 'Una soluzione della riga sopra va persa',
  'This lets in a solution the line above did not have': 'Questo introduce una soluzione che la riga sopra non aveva',
  'I read:': 'Ho letto:',
  'For example:': 'Per esempio:',
  'It works out to:': 'Viene:',
  'The solution that is missing:': 'La soluzione che manca:',
  'The solution that is new:': 'La soluzione nuova:',
  'The line above has:': 'La riga sopra ha:',
  'It should be:': 'Dovrebbe essere:',
  'Checked by working it out in numbers on this device. If the writing was read wrongly, the check is wrong too.': 'Controllato calcolando con i numeri su questo dispositivo. Se la scrittura è stata letta male, anche il controllo è sbagliato.',
  'The formula model is not installed (see Settings)': 'Il modello di formule non è installato (vedi impostazioni)',
  'Checking...': 'Controllo in corso...',
  'A line could not be read': 'Non è stato possibile leggere una riga',
  'Nothing to check in this line': 'Niente da controllare in questa riga',
  'Check the maths in the selection': 'Controlla i calcoli nella selezione',
  'Spell checking': 'Controllo ortografico',
  'Underlines misspelled words in text boxes, the written document and (once read) handwriting, with suggestions. Needs a dictionary from the settings.': 'Sottolinea le parole scritte male nelle caselle di testo, nel documento scritto e nella scrittura a mano (una volta letta), con suggerimenti. Serve un dizionario delle impostazioni.',
  'Misspelled words get a wavy red line in text boxes and the written document; tap one for suggestions. A word is right if the dictionary of any language that is on takes it, so a note in two languages works. The dictionaries are the Hunspell dictionaries of the LibreOffice project, downloaded when you turn a language on (they are not part of the app and have licences of their own). Everything is checked on this device.': 'Le parole scritte male hanno una linea rossa ondulata nelle caselle di testo e nel documento scritto; tocca una parola per i suggerimenti. Una parola è corretta se la accetta il dizionario di una qualsiasi lingua attiva, quindi una nota in due lingue funziona. I dizionari sono i Hunspell del progetto LibreOffice, scaricati quando attivi una lingua (non fanno parte dell’app e hanno licenze proprie). Tutto viene controllato su questo dispositivo.',
  'Your own words': 'Le tue parole',
  'Add a word': 'Aggiungi una parola',
  'Download about {size} MB': 'Scarica circa {size} MB',
  'Licence: {licence}': 'Licenza: {licence}',
  'see the README': 'vedi il README',
  'Delete the dictionary': 'Elimina il dizionario',
  'Licence and README': 'Licenza e README',
  'Add to dictionary': 'Aggiungi al dizionario',
