  'Copied: {word}': 'Copiato: {word}',
  'Read as: {word}': 'Letto come: {word}',
  'Mark words that are spelled right': 'Segna le parole scritte correttamente',
  'In handwriting, a green dotted line under each word that was read and found right (tap it to see what it was read as), to check that your writing was taken for writing.': 'Nella scrittura a mano, una linea verde tratteggiata sotto ogni parola letta e ritenuta corretta (toccala per vedere come è stata letta), per verificare che la tua scrittura sia stata presa come scrittura.',
  'This does not hold for:': 'Questo non vale per:',
  'This is not true': 'Questo non è vero',
