  'I am not sure I read this right': 'Non sono sicuro di aver letto bene questo',
  'As I read it, this is a mistake, but the writing can be read another way (below). Pick what you wrote:': 'Come lo leggo, è un errore, ma la scrittura si può leggere in un altro modo (sotto). Scegli cosa hai scritto:',
  'Or did you write:': 'Oppure hai scritto:',
  'Looked again: it reads the same': 'Riletto: si legge allo stesso modo',
  'Looking again...': 'Rileggo...',
  'The units are:': 'Le unità sono:',
  'Its determinant:': 'Il suo determinante:',
  'They differ at:': 'Differiscono in:',
  'I read (correct it if it is wrong):': 'Ho letto (correggi se è sbagliato):',
  'Checked by working it out in numbers on this device. If the writing was read wrongly, correct it above: the check is done again.': 'Controllato calcolando con i numeri su questo dispositivo. Se la scrittura è stata letta male, correggila sopra: il controllo viene rifatto.',
  'Suggestions are put in order with a list of the most common words of the language (FrequencyWords by Hermit Dave, from film and television subtitles, licence CC BY-SA 4.0), downloaded with the dictionary.': 'I suggerimenti sono ordinati con un elenco delle parole più comuni della lingua (FrequencyWords di Hermit Dave, dai sottotitoli di film e serie, licenza CC BY-SA 4.0), scaricato con il dizionario.',
  'General': 'Generali',
  'Tools and writing': 'Strumenti e scrittura',
  'AI and models': 'IA e modelli',
  'Sync and sharing': 'Sincronizzazione e condivisione',
  'A Nextcloud calendar is connected in the settings under Sync and sharing, with the other services.': 'Un calendario Nextcloud è collegato nelle impostazioni, sotto Sincronizzazione e condivisione, insieme agli altri servizi.',
  'Extensions': 'Estensioni',
  'Extensions are small scripts (JavaScript) that add tools to the menu of selected text and actions to the automations. Each runs in a sandbox: it cannot reach your files, the network or your notes unless you give it that permission, it is stopped if it runs too long or uses too much memory, and it is off until you switch it on. Only install extensions from people you trust.': 'Le estensioni sono piccoli script (JavaScript) che aggiungono strumenti al menu del testo selezionato e azioni alle automazioni. Ognuna gira in una sandbox: non può accedere ai tuoi file, alla rete o alle tue note se non le dai quel permesso, viene fermata se gira troppo a lungo o usa troppa memoria, ed è disattivata finché non la attivi. Installa solo estensioni di persone di cui ti fidi.',
  'Install from a file (.zip)': 'Installa da un file (.zip)',
  'Write one': 'Scrivine una',
  'Write an extension': 'Scrivi un’estensione',
  'The manifest says what it is called, what it adds and what it asks to be allowed to do (JSON):': 'Il manifesto dice come si chiama, cosa aggiunge e cosa chiede di poter fare (JSON):',
  'The script (JavaScript):': 'Lo script (JavaScript):',
  'Install': 'Installa',
  'No extensions yet.': 'Ancora nessuna estensione.',
  'The script engine is not available on this device: extensions cannot run.': 'Il motore degli script non è disponibile su questo dispositivo: le estensioni non possono funzionare.',
  'Extensions do not run in the browser: a script there could reach your notes, as the browser cannot keep it apart from them. Use the app on a computer or phone for them.': 'Le estensioni non funzionano nel browser: uno script lì potrebbe raggiungere le tue note, perché il browser non può tenerlo separato da esse. Usa l’app su un computer o un telefono per queste.',
  'Could not install it: {error}': 'Impossibile installarla: {error}',
  'Installed {name}. It is off until you switch it on.': '{name} installata. È disattivata finché non la attivi.',
  'It asks to be allowed to:': 'Chiede di poter:',
  'Nothing: it only works on the text it is given.': 'Niente: lavora solo sul testo che riceve.',
  'Actions': 'Azioni',
  '{name}: {error}': '{name}: {error}',
  'The text changed meanwhile: the result was not put in': 'Nel frattempo il testo è cambiato: il risultato non è stato inserito',
  'Read the text and the title of the note it is used on': 'Leggere il testo e il titolo della nota su cui viene usata',
  'Change the text and the title of the note it is used on': 'Modificare il testo e il titolo della nota su cui viene usata',
  'Add tasks to your calendar': 'Aggiungere attività al calendario',
  'Put text on the clipboard': 'Mettere del testo negli appunti',
  'Send requests to the websites it lists': 'Inviare richieste ai siti web che elenca',
  'Run an action of an extension': 'Eseguire un’azione di un’estensione',
  'Extensions are not available here': 'Le estensioni non sono disponibili qui',
