  'An extension action that is not installed': 'Un’azione di estensione non installata',
  'No extension has an action to run. Install one in Settings > Extensions and switch it on.': 'Nessuna estensione ha un’azione da eseguire. Installane una in Impostazioni > Estensioni e attivala.',
  'Runs an action of an extension, with the permissions you gave it. What it returns is shown as the result of the automation.': 'Esegue un’azione di un’estensione, con i permessi che le hai dato. Ciò che restituisce viene mostrato come risultato dell’automazione.',
  'Choose an action': 'Scegli un’azione',
  'Reading the writing ahead of time while the note is open': 'Lettura anticipata della scrittura mentre la nota è aperta',
  'While the note is open, the pen strokes that lie close together are grouped and, after things have been quiet for a moment (never while you draw), read in the background. When you then select that writing and convert it, the result is there at once. Needs the models from Settings. Nothing is changed in the note.': 'Mentre la nota è aperta, i tratti di penna vicini tra loro vengono raggruppati e, quando per un momento tutto è fermo (mai mentre disegni), letti in background. Quando poi selezioni quella scrittura e la converti, il risultato è già lì. Richiede i modelli delle impostazioni. Nella nota non cambia nulla.',
  'Handwriting and formulas': 'Scrittura a mano e formule',
