  'Make handwriting selectable in exported PDFs': 'Rendi la scrittura a mano selezionabile nei PDF esportati',
  'Puts what the writing says under it, out of sight, so that a PDF viewer can select, copy and search it. What was not read yet is read while the PDF is made (up to a minute).': 'Mette sotto, fuori vista, ciò che dice la scrittura, così un visualizzatore PDF può selezionarla, copiarla e cercarla. Ciò che non è ancora stato letto viene letto durante la creazione del PDF (fino a un minuto).',
