  'Pen and fingers': 'Penna e dita',
  'For a stylus on a tablet or a screen that has one. A pen that cannot tell how hard it presses draws lines of one thickness.': 'Per uno stilo su un tablet o su uno schermo che ne ha uno. Una penna che non sa quanta pressione esercita disegna linee di un solo spessore.',
  'Thicker lines where the pen presses harder': 'Linee più spesse dove la penna preme di più',
  'Sensitivity': 'Sensibilità',
  'Fewer tools': 'Meno strumenti',
  'More tools: guides, stabiliser, symmetry, onion skin, straightening, clear the page': 'Più strumenti: guide, stabilizzatore, simmetria, carta velina, raddrizzamento, pulisci la pagina',
  'Export with layers (OpenRaster, for Krita or GIMP)': 'Esporta con livelli (OpenRaster, per Krita o GIMP)',
  'Response': 'Risposta',
  'Soft: a light touch already gives a thick line. Firm: it takes a hard press.': 'Morbida: un tocco leggero dà già una linea spessa. Decisa: serve premere forte.',
  'Tilt thickens': 'L’inclinazione ingrossa',
  'A pen that reports how far it leans draws thicker lines when held flat, like the side of a pencil.': 'Una penna che segnala quanto è inclinata disegna linee più spesse se tenuta piatta, come il lato di una matita.',
  'Button on the side of the pen (held down)': 'Pulsante sul lato della penna (tenuto premuto)',
  'A finger': 'Un dito',
  'Once the pen has been used, fingers only scroll and zoom, so that a resting hand does not write.': 'Una volta usata la penna, le dita servono solo a scorrere e ingrandire, così una mano appoggiata non scrive.',
  'Fingers never write; only the pen (or a mouse) does.': 'Le dita non scrivono mai; scrive solo la penna (o un mouse).',
  'Fingers write too, also when a pen is in use.': 'Anche le dita scrivono, pure quando è in uso una penna.',
  'Show a ring where the pen hovers': 'Mostra un anello dove la penna passa sopra',
  'As big as the line it would draw.': 'Grande quanto la linea che disegnerebbe.',
