  'Passphrase': 'Frase d’accesso',
  'Passcode': 'Codice d’accesso',
  'That is not the passphrase.': 'Questa non è la frase d’accesso.',
  'That is not the passcode.': 'Questo non è il codice d’accesso.',
  'Show': 'Mostra',
  'Hide': 'Nascondi',
  'Unlock': 'Sblocca',
  'Unlock the note': 'Sblocca la nota',
  'Use fingerprint or face': 'Usa impronta o volto',
  'Lock this note': 'Blocca questa nota',
  'Lock this note...': 'Blocca questa nota...',
  'Use at least 6 characters.': 'Usa almeno 6 caratteri.',
  'Use at least 4 characters.': 'Usa almeno 4 caratteri.',
  'The two entries are not the same.': 'Le due voci non sono uguali.',
  'Keeps the note out of sight: its title is hidden and it asks for the passcode to open. The content is stored as usual, so this does not protect against someone who reads the files of the app.': 'Tiene la nota fuori dalla vista: il titolo è nascosto e chiede il codice d’accesso per aprirsi. Il contenuto è salvato come al solito, quindi questo non protegge da chi legge i file dell’app.',
  'Encrypts the whole note, its title too, with a passphrase. Nothing of it is stored in plain, except while it is open. If you forget the passphrase, the note is lost for good.': 'Cifra l’intera nota, titolo compreso, con una frase d’accesso. Nulla di essa è salvato in chiaro, tranne mentre è aperta. Se dimentichi la frase d’accesso, la nota è persa per sempre.',
  'Encrypted': 'Cifrata',
  'Once more': 'Ancora una volta',
  'Open with fingerprint or face': 'Apri con impronta o volto',
