  'The passage has few of the words of the statement: it may say it differently, or not at all.': 'Il passaggio ha poche delle parole dell’affermazione: potrebbe dirla diversamente, o non dirla affatto.',
  'Statements with no source named: {n}': 'Affermazioni senza fonte citata: {n}',
  'This answer names no passage of your notes: it may come from the model, not from them.': 'Questa risposta non cita alcun passaggio delle tue note: potrebbe venire dal modello, non dalle tue note.',
  'Named, but not among what was read': 'Citato, ma non tra ciò che è stato letto',
