  'New event': 'Nuovo evento',
  'Put tasks on a calendar': 'Metti attività in un calendario',
  'Ask your notes': 'Chiedi alle tue note',
  'Ask anything: the notes that fit your question are found first, then the passages in them that answer it.': 'Chiedi quello che vuoi: prima si trovano le note adatte alla tua domanda, poi i passaggi al loro interno che rispondono.',
  'What did I write about deadlines?': 'Cosa ho scritto sulle scadenze?',
  'Summarize my latest notes': 'Riassumi le mie ultime note',
  'Where did I note something about exams?': 'Dove ho annotato qualcosa sugli esami?',
  'There is nothing to read yet.': 'Non c’è ancora niente da leggere.',
  'This device has no speech program (install speech-dispatcher or espeak-ng).': 'Questo dispositivo non ha un programma di sintesi vocale (installa speech-dispatcher o espeak-ng).',
  'Getting the voice ready... (press to stop)': 'Preparazione della voce... (premi per fermare)',
  'The speech engine of this device did not take the text (is a voice installed?).': 'Il motore vocale di questo dispositivo non ha accettato il testo (c’è una voce installata?).',
  'The speech engine of this device did not start (is a voice installed in the system settings?).': 'Il motore vocale di questo dispositivo non si è avviato (c’è una voce installata nelle impostazioni di sistema?).',
  'The speech program made no sound.': 'Il programma di sintesi vocale non ha prodotto alcun suono.',
  'This device has no working speech engine. Install one (for example eSpeak NG or SherpaTTS from F-Droid) and choose it in the system settings under Text-to-speech.': 'Questo dispositivo non ha un motore vocale funzionante. Installane uno (per esempio eSpeak NG o SherpaTTS da F-Droid) e sceglilo nelle impostazioni di sistema, sotto Sintesi vocale.',
  'Summary, presentation, quiz...': 'Riassunto, presentazione, quiz...',
  'What are the key terms and what do they mean?': 'Quali sono i termini chiave e cosa significano?',
  'What is unclear or missing?': 'Cosa non è chiaro o manca?',
  'Make something from this note': 'Crea qualcosa da questa nota',
  'It is kept with the note, so it is made only once.': 'Viene conservato con la nota, quindi si crea una sola volta.',
  'What the AI made of this note, and what it can make': 'Ciò che l’IA ha ricavato da questa nota e ciò che ne può fare',
  'Cards to learn the note by, one question each.': 'Schede per studiare la nota, una domanda ciascuna.',
  '{name}: page {n}': '{name}: pagina {n}',
  'Go to the page': 'Vai alla pagina',
  'Leave this profile?': 'Lasciare questo profilo?',
  'This device stops syncing and forgets the other devices. The notes on it stay. The other devices keep the profile.': 'Questo dispositivo smette di sincronizzarsi e dimentica gli altri dispositivi. Le note che contiene restano. Gli altri dispositivi conservano il profilo.',
  'Leave this profile': 'Lascia questo profilo',
  'Sync profile': 'Profilo di sincronizzazione',
  'Use Notation on several devices as one person: the same id and name, the same notes and folders, the same settings. The devices connect directly to each other; the signalling server only introduces them.': 'Usa Notation su più dispositivi come una sola persona: stesso ID e nome, stesse note e cartelle, stesse impostazioni. I dispositivi si collegano direttamente tra loro; il server di segnalazione li presenta soltanto.',
  'Add a device': 'Aggiungi un dispositivo',
  'Use a link from another device': 'Usa un link da un altro dispositivo',
  'Name of this device': 'Nome di questo dispositivo',
  'No other device yet. Add one with a link.': 'Ancora nessun altro dispositivo. Aggiungine uno con un link.',
  'Syncing...': 'Sincronizzazione...',
  'Online': 'Online',
  'Not online': 'Offline',
  'synced {when}': 'sincronizzato {when}',
  'Take this device out of the profile': 'Rimuovi questo dispositivo dal profilo',
  'Looking for your other devices...': 'Ricerca degli altri dispositivi...',
  'Keep my devices in sync automatically': 'Mantieni i miei dispositivi sincronizzati automaticamente',
  'Done: the device is part of your profile now.': 'Fatto: il dispositivo ora fa parte del tuo profilo.',
  'On the other device open Notation, go to Settings → Sync profile → "Use a link from another device" (or the first screen of the app) and enter this link:': 'Sull’altro dispositivo apri Notation, vai su Impostazioni → Profilo di sincronizzazione → «Usa un link da un altro dispositivo» (o la prima schermata dell’app) e inserisci questo link:',
  'Notation: add a device': 'Notation: aggiungi un dispositivo',
  'The link holds the secret of your profile: send it only to yourself. It works for ten minutes, and a device in it still has to be let in here.': 'Il link contiene il segreto del tuo profilo: invialo solo a te stesso. Vale dieci minuti, e un dispositivo che lo usa deve comunque essere accettato qui.',
  '{name} wants to join your profile': '{name} vuole unirsi al tuo profilo',
  'Is this the code on that device?': 'È questo il codice mostrato su quel dispositivo?',
  'No, that is not my device': 'No, non è il mio dispositivo',
  'Yes, let it in': 'Sì, fallo entrare',
  'That is not a link to add a device.': 'Questo non è un link per aggiungere un dispositivo.',
  'Done: this device is part of the profile now. Its notes, folders and settings are being brought together.': 'Fatto: questo dispositivo ora fa parte del profilo. Le sue note, cartelle e impostazioni sono in fase di unione.',
  'This code must be the same on the other device:': 'Questo codice deve essere uguale sull’altro dispositivo:',
  'If it differs, press Cancel: someone else may be in the way.': 'Se è diverso, premi Annulla: potrebbe esserci qualcun altro di mezzo.',
  'This device takes over the id and name of that profile. Its own notes stay and are brought together with the others.': 'Questo dispositivo prende l’ID e il nome di quel profilo. Le sue note restano e vengono unite alle altre.',
  'Looking for the device that made the link...': 'Ricerca del dispositivo che ha creato il link...',
  'Waiting for the other device to say yes': 'In attesa che l’altro dispositivo dica sì',
  'There is no signalling server: set one in the live collaboration settings.': 'Non c’è un server di segnalazione: impostane uno nelle impostazioni di collaborazione dal vivo.',
  'The device that made the link was not found. Is it online, and is its link still on offer?': 'Il dispositivo che ha creato il link non è stato trovato. È online, e il suo link è ancora disponibile?',
  'The signalling server could not be reached: {error}': 'Impossibile raggiungere il server di segnalazione: {error}',
  'The connection to the other device was lost': 'La connessione con l’altro dispositivo si è interrotta',
  'The other device did not answer': 'L’altro dispositivo non ha risposto',
  'The other device did not follow the protocol': 'L’altro dispositivo non ha seguito il protocollo',
  'The other device runs a different version of the sync': 'L’altro dispositivo usa un’altra versione della sincronizzazione',
  'The other device did not say who it is': 'L’altro dispositivo non ha detto chi è',
  'The other devices have another key for this device than the one it signs with, so they refuse it. Sign out of the profile on this device and sign in again.': 'Gli altri dispositivi hanno per questo una chiave diversa da quella con cui firma, quindi lo rifiutano. Esci dal profilo su questo dispositivo e accedi di nuovo.',
  'The key of the other device is not the one that was accepted': 'La chiave dell’altro dispositivo non è quella che era stata accettata',
  'The other device could not prove who it is': 'L’altro dispositivo non ha potuto dimostrare chi è',
  'Comparing the devices...': 'Confronto dei dispositivi...',
  'This device was removed from the profile': 'Questo dispositivo è stato rimosso dal profilo',
  'The other device was removed from the profile': 'L’altro dispositivo è stato rimosso dal profilo',
  'Looking at what changed...': 'Verifica di cosa è cambiato...',
  'Sending notes...': 'Invio delle note...',
  'Receiving...': 'Ricezione...',
  'A new device asks to join': 'Un nuovo dispositivo chiede di unirsi',
  'You did not let the new device in': 'Non hai fatto entrare il nuovo dispositivo',
  'The other device did not let this one in': 'L’altro dispositivo non ha fatto entrare questo',
  'This device is not one of this profile (add it with the link from a device of the profile)': 'Questo dispositivo non fa parte di questo profilo (aggiungilo con il link di un dispositivo del profilo)',
  'from before the sync': 'di prima della sincronizzazione',
  'The server did not accept this device': 'Il server non ha accettato questo dispositivo',
  'No connection could be made to the other device. Networks that block direct connections need a TURN server.': 'Non è stato possibile collegarsi all’altro dispositivo. Le reti che bloccano le connessioni dirette hanno bisogno di un server TURN.',
  'Already use Notation on another device?': 'Usi già Notation su un altro dispositivo?',
  'Sync this device with it: the same id and name, notes, folders and settings.': 'Sincronizza questo dispositivo con quello: stesso ID e nome, note, cartelle e impostazioni.',
  'Use a link from that device': 'Usa un link da quel dispositivo',
  'Online status not known': 'Stato online sconosciuto',
  'This device is not in the meeting room, so it cannot see which of your other devices are online. Turn on the automatic sync below, or press "Sync now" on both devices.': 'Questo dispositivo non è nella sala riunioni, quindi non può vedere quali altri dispositivi sono online. Attiva la sincronizzazione automatica qui sotto, o premi «Sincronizza ora» su entrambi i dispositivi.',
  'Look for my other devices from time to time': 'Cerca ogni tanto i miei altri dispositivi',
  'When the app starts, when it comes to the front and every ten minutes, this device joins the meeting room for a minute and syncs if another device of yours is there. The server only learns of these short visits. Two devices that both only look from time to time meet only when their visits overlap; one that stays connected is always found.': 'All’avvio dell’app, quando torna in primo piano e ogni dieci minuti, questo dispositivo entra nella sala riunioni per un minuto e si sincronizza se un altro dei tuoi dispositivi è lì. Il server viene a sapere solo di queste brevi visite. Due dispositivi che cercano solo ogni tanto si incontrano solo se le visite si sovrappongono; uno che resta connesso viene sempre trovato.',
  'If it differs, say so: someone else may be in the way. Nothing of the other device is taken over until you say it is the same.': 'Se è diverso, diglielo: potrebbe esserci qualcun altro di mezzo. Non viene preso nulla dall’altro dispositivo finché non confermi che è lo stesso.',
  'It is different': 'È diverso',
  'It is the same': 'È lo stesso',
  'The codes were not the same, so this device was not added': 'I codici non coincidevano, quindi questo dispositivo non è stato aggiunto',
  'The other device did not keep to what it first said': 'L’altro dispositivo non ha mantenuto ciò che aveva detto all’inizio',
  'Stop reading': 'Smetti di leggere',
  'Read the note aloud': 'Leggi la nota ad alta voce',
  'The event must end after it starts.': 'L’evento deve finire dopo l’inizio.',
  'Notes': 'Note',
  'Tasks on a calendar': 'Attività in un calendario',
  'A task with a day can also be put on a calendar as an all-day event, so that it shows up in the calendar app of the phone or of the server. It goes again when the task is done or deleted.': 'Un’attività con una data può anche essere messa in un calendario come evento di tutto il giorno, così compare nell’app calendario del telefono o del server. Viene rimossa quando l’attività è completata o eliminata.',
  'There is no calendar to put them on: connect a server or turn on a calendar of the phone first (both must allow writing).': 'Non c’è un calendario dove metterle: collega prima un server o attiva un calendario del telefono (entrambi devono consentire la scrittura).',
  'Not on a calendar': 'Non in un calendario',
  'Only the tasks that were made by an automation or found in a note': 'Solo le attività create da un’automazione o trovate in una nota',
  'What the AI can make of this note': 'Cosa l’IA può ricavare da questa nota',
  'Starting...': 'Avvio...',
  'There is nothing to make a graph of yet: the notes have no text.': 'Non c’è ancora nulla da cui fare un grafo: le note non hanno testo.',
  'Graph': 'Grafo',
  'Facts': 'Dati',
  'This graph was made before the sentence model was installed, so its topics follow shared words. Make it again to use the model.': 'Questo grafo è stato fatto prima dell’installazione del modello di frasi, quindi i suoi temi seguono le parole in comune. Rifallo per usare il modello.',
  'No sentence model is installed: topics will follow shared words, not meaning (Settings, AI and models).': 'Nessun modello di frasi è installato: i temi seguiranno le parole in comune, non il significato (Impostazioni, IA e modelli).',
  'Name the topics with the AI model': 'Dai nome ai temi con il modello IA',
  'One short request for every 20 topics. A topic that stays about the same keeps its name when the graph is made again.': 'Una richiesta breve ogni 20 temi. Un tema che resta più o meno uguale mantiene il suo nome quando il grafo viene rifatto.',
  'the picture before ({when})': 'l’immagine precedente ({when})',
  'Nothing to compare with yet: make this graph again, or make a second graph of the same kind.': 'Niente con cui confrontare: rifai questo grafo, o creane un secondo dello stesso tipo.',
  'Earlier picture: {when} ({n} nodes)': 'Immagine precedente: {when} ({n} nodi)',
