  'The graph of facts shows what your notes say, grouped by topic. Making it reads all notes, so it is not made on its own.': 'Il grafo dei dati mostra ciò che dicono le tue note, raggruppato per tema. Crearlo legge tutte le note, quindi non si fa da solo.',
