  'Point the camera at the code that "Add a device" shows on the other device.': 'Punta la fotocamera sul codice che «Aggiungi un dispositivo» mostra sull’altro dispositivo.',
  'On a device that is already in the profile, go to Settings → Sync profile → "Add a device". Scan the code it shows or paste the link:': 'Su un dispositivo già nel profilo, vai su Impostazioni → Profilo di sincronizzazione → «Aggiungi un dispositivo». Scansiona il codice che mostra o incolla il link:',
  'Writing the facts needs an AI model: set one up in the Settings (on this device, or a service), or choose another one with the arrows above.': 'Scrivere i dati richiede un modello IA: configurane uno nelle impostazioni (su questo dispositivo o su un servizio), oppure sceglierne un altro con le frecce qui sopra.',
