  'No account for the chosen service on this device yet: connect it in the Settings, or let it come from your other device when they sync directly.': 'Non c’è ancora un account per il servizio scelto su questo dispositivo: collegalo nelle impostazioni, o lascia che arrivi dall’altro dispositivo quando sincronizzate direttamente.',
