  'No cloud account is connected on this device. Connect one (Nextcloud in the settings under Sync and sharing, or S3, Dropbox or OneDrive under sharing), or sync directly with the device that has one.': 'Su questo dispositivo non è collegato nessun account cloud. Collegane uno (Nextcloud nelle impostazioni, sotto Sincronizzazione e condivisione, oppure S3, Dropbox o OneDrive sotto Condivisione), oppure sincronizza direttamente con il dispositivo che ne ha uno.',
  'Service': 'Servizio',
  'not connected': 'non collegato',
  'Folder name': 'Nome della cartella',
  'Every file is sealed with a key from your profile, and the names say nothing. The cloud holds files nobody can read; only your devices can.': 'Ogni file è sigillato con una chiave del tuo profilo, e i nomi non dicono nulla. Il cloud contiene file che nessuno può leggere; solo i tuoi dispositivi possono.',
  'Not encrypted': 'Non cifrato',
  'Notes are normal .uninote files and the list is readable text, so you can open them yourself from the cloud. Anyone who can see the folder can read your notes.': 'Le note sono normali file .uninote e la lista è testo leggibile, quindi puoi aprirli tu stesso dal cloud. Chiunque possa vedere la cartella può leggere le tue note.',
