  'What was changed on "{from}" since it was branched off (or last merged) is taken into the note. Where both were changed, the note keeps its own. The note as it is now is kept as a version first, so this can be undone.': 'Ciò che è stato modificato su «{from}» dalla diramazione (o dall’ultima unione) viene portato nella nota. Dove sono state modificate entrambe, la nota tiene la propria. La nota com’è adesso viene prima conservata come versione, così si può annullare.',
  'Merge': 'Unisci',
