  'Installed {name}. It is off until you switch it on; then its tools ({tools}) are in the menu of selected text, as "{name}: ...".': '{name} installata. È disattivata finché non la attivi; allora i suoi strumenti ({tools}) sono nel menu del testo selezionato, come «{name}: ...».',
  '{name} is installed and switched on.': '{name} è installata e attivata.',
  'Installed {name}. It is off until you switch it on in Settings > Extensions.': '{name} installata. È disattivata finché non la attivi in Impostazioni > Estensioni.',
  'One automation was added.': 'È stata aggiunta un’automazione.',
  '{n} automations were added.': 'Sono state aggiunte {n} automazioni.',
  'They are off.': 'Sono disattivate.',
  'Create with AI': 'Crea con l’IA',
  'Say what you want in your own words: a tool for selected text, or something that should happen by itself. The AI writes the extension, you read it, and only then is it installed.': 'Descrivi ciò che vuoi con parole tue: uno strumento per il testo selezionato, o qualcosa che deve accadere da solo. L’IA scrive l’estensione, tu la leggi, e solo dopo viene installata.',
  'e.g. A tool that turns the selected lines into a checklist. Or: when a note has not been opened for a month, add a task to look at it.': 'ad es. Uno strumento che trasforma le righe selezionate in una lista di controllo. Oppure: quando una nota non è aperta da un mese, aggiungere un’attività per rivederla.',
  'What is sent to the AI you chose in Settings: the description of the extension API and your request. No notes, no files. With an AI in the cloud that leaves this device.': 'Ciò che viene inviato all’IA scelta nelle impostazioni: la descrizione dell’API delle estensioni e la tua richiesta. Nessuna nota, nessun file. Con un’IA nel cloud, questo lascia il dispositivo.',
  'The AI is writing it...': 'L’IA sta scrivendo l’estensione...',
