  'Install puts it in the list switched off and without any permission. Install and allow also switches it on and gives it the permissions above.': 'Installa la mette nell’elenco disattivata e senza alcun permesso. Installa e consenti la attiva anche e le dà i permessi qui sopra.',
  'Read the documentation': 'Leggi la documentazione',
