  'Studying needs an AI model: set one up in the Settings (on this device, or a service).': 'Studiare richiede un modello IA: configurane uno nelle impostazioni (su questo dispositivo o su un servizio).',
  'The AI did not write any usable cards. Try again.': 'L’IA non ha scritto schede utilizzabili. Riprova.',
  'The AI did not write any usable questions. Try again.': 'L’IA non ha scritto domande utilizzabili. Riprova.',
