  'This device is not part of a sync profile yet, so there is nothing to sync through the folder.': 'Questo dispositivo non fa ancora parte di un profilo di sincronizzazione, quindi non c’è nulla da sincronizzare tramite la cartella.',
  'Waiting for the direct sync with your other device to end...': 'In attesa che termini la sincronizzazione diretta con l’altro dispositivo...',
