  'Share this folder with a person': 'Condividi questa cartella con una persona',
  'Invites someone who has an account at the same cloud service. They see it in their own account and in the app, and can only do what you allow. Changes go both ways. The files are not sealed: the cloud service can read what you share.': 'Invita qualcuno che ha un account presso lo stesso servizio cloud. Lo vede nel proprio account e nell’app, e può fare solo ciò che consenti. Le modifiche vanno in entrambi i sensi. I file non sono sigillati: il servizio cloud può leggere ciò che condividi.',
