  'That folder is gone': 'Quella cartella non c’è più',
  'This device is not part of a sync profile yet.': 'Questo dispositivo non fa ancora parte di un profilo di sincronizzazione.',
  'The share was withdrawn. What you have of it stays.': 'La condivisione è stata ritirata. Ciò che ne hai resta.',
  'The owner removed this. What you have of it stays.': 'Il proprietario lo ha rimosso. Ciò che ne hai resta.',
  'This is not a share from Notation, or from a newer version of it.': 'Questa non è una condivisione di Notation, né di una versione più recente.',
  'You have this {what} already, and not from this share. Delete it here first to take the share in.': 'Hai già questo {what}, e non viene da questa condivisione. Eliminalo prima qui per accettare la condivisione.',
  'note': 'nota',
  'folder': 'cartella',
  'The Nextcloud allows only a few new shares in a short time. Try again in a few minutes.': 'Nextcloud consente solo poche nuove condivisioni in poco tempo. Riprova tra qualche minuto.',
  'This Nextcloud does not offer sharing with people.': 'Questo Nextcloud non offre la condivisione con persone.',
  'The Nextcloud did not share the folder.': 'Nextcloud non ha condiviso la cartella.',
  'The Nextcloud did not accept the share.': 'Nextcloud non ha accettato la condivisione.',
  'Allow sharing with people in the OneDrive settings first (it needs access to all your files).': 'Prima consenti la condivisione con persone nelle impostazioni di OneDrive (serve l’accesso a tutti i tuoi file).',
  'Sign in to OneDrive again, so that it can be allowed to share.': 'Accedi di nuovo a OneDrive, così può essere consentita la condivisione.',
  'OneDrive does not allow sharing with this person here (an administrator can forbid it for work and school accounts).': 'OneDrive non consente la condivisione con questa persona qui (un amministratore può vietarla per account di lavoro e scolastici).',
  'OneDrive says to wait a little. Try again in a few minutes.': 'OneDrive chiede di aspettare un po’. Riprova tra qualche minuto.',
  'The shared folder is not on your OneDrive (any more).': 'La cartella condivisa non è (più) sul tuo OneDrive.',
  'Shared with Notation. Open the link in the invitation, or add it in the app: Settings, Sync and sharing.': 'Condiviso con Notation. Apri il link nell’invito, o aggiungilo nell’app: Impostazioni, Sincronizzazione e condivisione.',
  'OneDrive did not share the folder.': 'OneDrive non ha condiviso la cartella.',
  'This is not a link to a share.': 'Questo non è un link a una condivisione.',
  'This link does not open a shared folder for you. Are you signed in with the account that was invited?': 'Questo link non ti apre alcuna cartella condivisa. Hai effettuato l’accesso con l’account invitato?',
  'This is not a share from Notation.': 'Questa non è una condivisione di Notation.',
  'You have this share already.': 'Hai già questa condivisione.',
  'Allow sharing with people in the Dropbox settings first (it needs a Dropbox app with access to the whole Dropbox).': 'Prima consenti la condivisione con persone nelle impostazioni di Dropbox (serve un’app Dropbox con accesso a tutto Dropbox).',
  'Sign in to Dropbox again, so that it can be allowed to share.': 'Accedi di nuovo a Dropbox, così può essere consentita la condivisione.',
  'Dropbox says to wait a little. Try again in a few minutes.': 'Dropbox chiede di aspettare un po’. Riprova tra qualche minuto.',
  'This Dropbox app is not allowed to share. It has to be registered with access to the whole Dropbox, and with the sharing permissions.': 'Questa app Dropbox non può condividere. Deve essere registrata con accesso a tutto Dropbox e con i permessi di condivisione.',
  'Your Dropbox e-mail address has to be verified before you can share.': 'Il tuo indirizzo e-mail Dropbox deve essere verificato prima di poter condividere.',
  'Your Dropbox plan does not allow sharing with this many people.': 'Il tuo piano Dropbox non consente di condividere con così tante persone.',
  'The shared folder is not on your Dropbox (any more).': 'La cartella condivisa non è (più) nel tuo Dropbox.',
  'Dropbox did not do it.': 'Dropbox non l’ha fatto.',
  'Dropbox did not share the folder.': 'Dropbox non ha condiviso la cartella.',
  'Dropbox is slow to share the folder. Try again in a moment.': 'Dropbox è lento a condividere la cartella. Riprova tra un momento.',
  'Shared with Notation. Accept it in your Dropbox, then it is listed in the app: Settings, Sync and sharing.': 'Condiviso con Notation. Accettalo nel tuo Dropbox, poi compare nell’app: Impostazioni, Sincronizzazione e condivisione.',
  'Dropbox did not accept the share.': 'Dropbox non ha accettato la condivisione.',
  'Link copied. Send it to {name}: they add it under Settings, Sync and sharing.': 'Link copiato. Invialo a {name}: lo aggiunge in Impostazioni, Sincronizzazione e condivisione.',
  'Copy the link to send to {name}': 'Copia il link da inviare a {name}',
  'A link to a share (OneDrive)': 'Un link a una condivisione (OneDrive)',
  '"{name}" is shared with you by {who}. Take it in under Settings, Sync and sharing.': '«{name}» ti è condiviso da {who}. Accettalo in Impostazioni, Sincronizzazione e condivisione.',
  'Also allow sharing with people': 'Consenti anche la condivisione con persone',
  'Sharing a folder with someone, and opening what they share with you, needs access to all your OneDrive files, not just the folder of the app. Changing this signs you out: sign in again afterwards. (Settings, Shared with people)': 'Condividere una cartella con qualcuno, e aprire ciò che condivide con te, richiede l’accesso a tutti i tuoi file OneDrive, non solo alla cartella dell’app. Cambiare questa impostazione ti disconnette: accedi di nuovo dopo. (Impostazioni, Condivisi con persone)',
  'Sharing a folder with someone, and opening what they share with you, only works with a Dropbox app that has access to the whole Dropbox (not the app folder alone), and the sharing permissions. Turn this on only if the app key above is such an app. Changing this signs you out: sign in again afterwards.': 'Condividere una cartella con qualcuno, e aprire ciò che condivide con te, funziona solo con un’app Dropbox che ha accesso a tutto Dropbox (non solo alla cartella dell’app), e con i permessi di condivisione. Attivalo solo se la chiave dell’app qui sopra è un’app così. Cambiare questa impostazione ti disconnette: accedi di nuovo dopo.',
