  '{done} of {total}': '{done} di {total}',
  'This note has no text boxes or written document to translate. Handwriting is not translated.': 'Questa nota non ha caselle di testo né documento scritto da tradurre. La scrittura a mano non viene tradotta.',
  'The text of the PDF is rewritten in its translation, page by page. Longer lines are set smaller, and a line that cannot be shown stays as it was. A version of the note is kept first, and the change can be taken back with Undo.': 'Il testo del PDF viene riscritto nella sua traduzione, pagina per pagina. Le righe più lunghe vengono composte più piccole, e una riga che non può essere mostrata resta com’era. Prima viene conservata una versione della nota, e la modifica si può annullare con Annulla.',
  'The {n} texts in this note are replaced by their translation, in place. A version of the note is kept first, and the change can be taken back with Undo.': 'I {n} testi di questa nota vengono sostituiti con la loro traduzione, sul posto. Prima viene conservata una versione della nota, e la modifica si può annullare con Annulla.',
  'The assistant is not ready. Set up a model in the Settings first.': 'L’assistente non è pronto. Configura prima un modello nelle impostazioni.',
