  'Drawings stay shapes you can edit in a vector program; layers become named groups. Text boxes and pictures are pictures in the file.': 'I disegni restano forme modificabili in un programma vettoriale; i livelli diventano gruppi con nome. Le caselle di testo e le immagini sono immagini nel file.',
