  'Alignment lines': 'Linee di allineamento',
  'Lines that show where a text box, picture or shape you are moving lines up with the others on the page (or the middle and edges of the page), and let it fall into place. Hold Alt to move freely.': 'Le linee che mostrano quando una casella di testo, un’immagine o una forma che stai spostando si allinea con le altre della pagina (o con il centro e i bordi della pagina), e la fanno scattare al loro posto. Tieni premuto Alt per spostare liberamente.',
