  'like "{text}"': 'come «{text}»',
  'Connect an AI agent': 'Collega un agente IA',
  'An AI agent on this computer (Claude Code, an editor with AI, any program that speaks the Model Context Protocol) can then find, read and write your notes, folders, tags and tasks. It connects to this app on this computer only, with the token below. Locked notes are never available to it, and it cannot delete a note for good. Every change to a note keeps a version of it before and after, which you can bring back. What the agent reads goes to the AI service it belongs to: connect only agents you trust with your notes.': 'Un agente IA su questo computer (Claude Code, un editor con IA, qualsiasi programma che parli il Model Context Protocol) può allora trovare, leggere e scrivere le tue note, cartelle, etichette e attività. Si collega solo a questa app su questo computer, con il token qui sotto. Le note bloccate non gli sono mai accessibili, e non può eliminare una nota per sempre. Ogni modifica a una nota conserva una versione prima e dopo, che puoi ripristinare. Ciò che l’agente legge va al servizio IA a cui appartiene: collega solo agenti di cui ti fidi con le tue note.',
