  'About {n} flashcards from the note, kept for review': 'Circa {n} schede di studio ricavate dalla nota, conservate per il ripasso',
  'Half a minute after the last change': 'Mezzo minuto dopo l’ultima modifica',
  'What this rule did': 'Cosa ha fatto questa regola',
  'There are no templates here.': 'Non ci sono modelli qui.',
  'Choose a template': 'Scegli un modello',
  'No template (a blank note)': 'Nessun modello (una nota vuota)',
  'A further step': 'Un passo in più',
  'Which trigger': 'Quale innesco',
  'Bind a key to "Run the automations of trigger 1" in the settings of the shortcuts, or set the side button of the pen to it (Settings, pen)': 'Assegna un tasto a «Esegui le automazioni dell’innesco 1» nelle impostazioni delle scorciatoie, oppure assegnaglielo dal pulsante laterale della penna (Impostazioni, penna)',
  'Minutes before it starts': 'Minuti prima dell’inizio',
  'Looked at every minute while the app runs; each event once': 'Controllato ogni minuto mentre l’app gira; ogni evento una volta sola',
  'A note whose title is empty or "Untitled Note" is named after what it says: the language model writes a short title if it is installed (Settings), else the first line is used when it is short enough. A note that has a title is never changed.': 'Una nota il cui titolo è vuoto o «Nota senza titolo» prende il nome da ciò che dice: il modello linguistico scrive un titolo breve se è installato (Impostazioni); altrimenti si usa la prima riga, se è abbastanza corta. Una nota che ha un titolo non viene mai cambiata.',
  'The assistant reads the text of the note and writes flashcards from it, which are kept for review (Flashcards, spaced repetition). A question that is kept already is not added again. Needs the assistant; a model on this device takes a minute or so.': 'L’assistente legge il testo della nota e ne ricava schede di studio, che vengono conservate per il ripasso (Schede di studio, ripetizione dilazionata). Una domanda già conservata non viene aggiunta di nuovo. Richiede l’assistente; un modello su questo dispositivo impiega un minuto circa.',
  'About how many cards': 'Quante schede più o meno',
  '{n} is how many cards are due. One task a day, today, while there are cards due': '{n} è il numero di schede da ripassare. Un’attività al giorno, oggi, finché ci sono schede da ripassare',
  'Then also, one after the other': 'Poi anche, una dopo l’altra',
  'Take this step out': 'Togli questo passo',
  'Add a step': 'Aggiungi un passo',
  'The steps run in the background, one after the other. Each can use {result}, what the one before said, in its text; a step that cannot do its work ends the chain.': 'I passi girano in background, uno dopo l’altro. Ciascuno può usare {result}, ciò che ha detto il precedente, nel suo testo; un passo che non riesce a fare il suo lavoro interrompe la catena.',
  'Dropbox needs an app of your own: create one at dropbox.com/developers/apps ("Scoped access", "App folder"), allow files.content.write, files.content.read, files.metadata.read and sharing.write, add the redirect URI notation://oauth/dropbox, and enter its app key here.': 'Dropbox richiede un’app propria: creala su dropbox.com/developers/apps («Scoped access», «App folder»), consenti files.content.write, files.content.read, files.metadata.read e sharing.write, aggiungi l’URI di reindirizzamento notation://oauth/dropbox e inserisci qui la sua chiave dell’app.',
  '"{address}" is not the address of a relay. Use something like turn:turn.example.org:3478': '«{address}» non è l’indirizzo di un relay. Usa qualcosa come turn:turn.example.org:3478',
  'Notation could not start': 'Notation non è riuscita ad avviarsi',
  'Nothing was deleted. Close the app and open it again; if this keeps happening, make sure the device has free storage and that this is not an older version of the app than the one that last ran.': 'Non è stato cancellato nulla. Chiudi l’app e riaprila; se succede ancora, controlla che il dispositivo abbia spazio libero e che non sia una versione dell’app più vecchia di quella che è girata per ultima.',
  'View': 'Vedi',
  'The quick brown fox jumps over the lazy dog.': 'Quel fiero pasto d’aglio ed ogni vezzo rende zia bizzarra.',
  'Sync problem': 'Problema di sincronizzazione',
