  'Arrange the toolbars': 'Disponi le barre degli strumenti',
  'Record the sound while you write: each line is tied to the moment it was written': 'Registra l’audio mentre scrivi: ogni riga è legata al momento in cui è stata scritta',
  'The microphone is not allowed (see the settings of the system)': 'Il microfono non è consentito (vedi le impostazioni del sistema)',
