  'Kept the sound with {n} lines tied to their moments': 'Audio conservato con {n} righe legate ai loro momenti',
  'Lecture {date}': 'Lettura {date}',
  'Play the sound from when this was written': 'Riproduci l’audio dal momento in cui questo è stato scritto',
  'The sound of this line is not there any more': 'L’audio di questa riga non c’è più',
  'Keep this mistake as a flashcard': 'Conserva questo errore come scheda di studio',
  'Kept it as a flashcard, to ask again later': 'Conservato come scheda di studio, da richiedere più tardi',
  'This mistake is a flashcard already': 'Questo errore è già una scheda di studio',
  'Edit text': 'Modifica testo',
  'Smaller': 'Più piccolo',
  'Bigger': 'Più grande',
  'Rotate': 'Ruota',
  'Change the toolbar profile': 'Cambia il profilo della barra degli strumenti',
  'Nothing here. Move a section over from the other bar.': 'Qui non c’è nulla. Sposta una sezione dall’altra barra.',
  'Profiles': 'Profili',
  'A profile keeps an arrangement of the toolbars with the tools it uses, so you can change between ways of working (drawing, maths...) in one tap.': 'Un profilo conserva una disposizione delle barre degli strumenti con gli strumenti che usa, così puoi passare da un modo di lavorare (disegno, matematica...) con un solo tocco.',
  'New profile': 'Nuovo profilo',
  'Tools in this profile': 'Strumenti di questo profilo',
  'The tools that are switched on in the settings. One that is off there is off in every profile.': 'Gli strumenti attivati nelle impostazioni. Uno disattivato lì è disattivato in ogni profilo.',
  '(new)': '(nuovo)',
  'This replaces version {version}.': 'Questo sostituisce la versione {version}.',
  'It is installed switched off and without any permission. You switch it on and give it these in Settings.': 'Viene installato disattivato e senza alcun permesso. Lo attivi e gli dai questi nelle impostazioni.',
  'The note was closed': 'La nota è stata chiusa',
  'Could not save the pictures: {error}': 'Impossibile salvare le immagini: {error}',
  'Saved 1 picture in {dir}': '1 immagine salvata in {dir}',
  'Saved {n} pictures in {dir}': '{n} immagini salvate in {dir}',
  '{n} fact': '{n} dato',
  '{n} facts': '{n} dati',
  'Possible contradictions': 'Possibili contraddizioni',
  'Facts that disagree': 'Dati discordanti',
  'These facts come from different notes, are about the same thing and give different numbers. One of them may be out of date, or both may be right in their own place.': 'Questi dati vengono da note diverse, riguardano la stessa cosa e danno numeri diversi. Uno dei due può essere superato, oppure entrambi possono essere giusti nel loro contesto.',
  'Says something else in {note}': 'Dice altro in {note}',
  'another note': 'un’altra nota',
  'Do you use these one at a time?': 'Li usi uno alla volta?',
  'Then give each its own toolbar profile: one tap changes the toolbars to the tools of that use only (drawing without the maths tools, and the other way around). All of them stay available; you can change the profiles whenever you like.': 'Allora dai a ciascuno il suo profilo di barra degli strumenti: un tocco cambia le barre sugli strumenti di quell’uso soltanto (disegno senza quelli di matematica, e viceversa). Restano tutti disponibili; puoi cambiare i profili quando vuoi.',
  'Make a profile for each: {names}': 'Crea un profilo per ciascuno: {names}',
  'Each toolbar profile uses its own share of these tools; what you switch off here is off in all of them.': 'Ogni profilo della barra degli strumenti usa la sua parte di questi strumenti; ciò che disattivi qui è disattivato in tutti.',
  'Create': 'Crea',
  'No automation is set for trigger {n} (see Automations)': 'Nessuna automazione è impostata per l’innesco {n} (vedi Automazioni)',
  'Trigger {trigger}: ran 1 automation': 'Innesco {trigger}: eseguita 1 automazione',
  'Trigger {trigger}: ran {n} automations': 'Innesco {trigger}: eseguite {n} automazioni',
  'Menu': 'Menu',
  'PDF sharpness': 'Nitidezza dei PDF',
  'The most PDF pages are drawn at. On screen a page is drawn as sharp as the screen shows it, up to this; zoomed in, the part on screen is drawn sharper. Pictures of pages that are exported use it as it is. Higher is sharper but uses more memory and loads slower. Automatic picks 250 dpi on a device with plenty of memory and 200 dpi on others. It applies to PDFs opened from now on.': 'A quale risoluzione vengono disegnate la maggior parte delle pagine PDF. A schermo una pagina viene disegnata nitida quanto lo schermo la mostra, fino a questo valore; con lo zoom la parte visibile viene disegnata più nitida. Le immagini delle pagine esportate la usano così com’è. Più alto è più nitido ma usa più memoria e si carica più lentamente. Automatico sceglie 250 dpi su un dispositivo con molta memoria e 200 dpi sugli altri. Vale per i PDF aperti da ora in poi.',
  'Automatic ({dpi} dpi on this device)': 'Automatico ({dpi} dpi su questo dispositivo)',
  'QR code': 'Codice QR',
  'Plan for an exam': 'Piano per un esame',
  'It could not be looked at.': 'Non è stato possibile esaminarlo.',
  'Say what should happen by itself, in your own words. The assistant writes the rule; you look at it, and at what it would have touched, before it is switched on.': 'Dì con parole tue cosa deve accadere da solo. L’assistente scrive la regola; tu la guardi, e ciò che toccherebbe, prima che venga attivata.',
  'For example: when I close a note in Physics, give it the tag lecture': 'Per esempio: quando chiudo una nota di Fisica, dalle l’etichetta lezione',
  'Write the rule': 'Scrivi la regola',
  'The assistant could not make a rule of that with what automations can do. Try saying it another way.': 'L’assistente non è riuscito a fare una regola di questo con ciò che le automazioni sanno fare. Prova a dirlo in un altro modo.',
  'Looking at what it would touch...': 'Verifica di ciò che toccherebbe...',
  'Added: see the list of automations.': 'Aggiunta: vedi l’elenco delle automazioni.',
  'Add, switched off': 'Aggiungi, disattivata',
  'Add and switch on': 'Aggiungi e attiva',
  '{n} line was left out': '{n} riga è stata omessa',
  '{n} lines were left out': '{n} righe sono state omesse',
  'Folder': 'Cartella',
  'Relay server (for mobile networks)': 'Server relay (per le reti mobili)',
  'Two devices connect to each other directly. On a mobile network, and behind some other networks, that does not work: a relay (a TURN server) then passes the data between them. It sees nothing of it, as everything is sealed. Run your own (coturn, say) or use a service that offers one, and enter its address and the name and password it gave you. This stays on this device; set it on the devices that are on such a network (it does not hurt on the others).': 'Due dispositivi si collegano direttamente tra loro. Su una rete mobile, e dietro alcune altre reti, questo non funziona: un relay (un server TURN) fa passare i dati tra i due. Non ne vede nulla, perché tutto è sigillato. Gestiscine uno tuo (coturn, per esempio) o usa un servizio che ne offre uno, e inserisci il suo indirizzo e il nome e la password che ti ha dato. Resta su questo dispositivo; impostalo sui dispositivi che sono su una rete così (non fa male sugli altri).',
  'Relay address': 'Indirizzo del relay',
  'Password': 'Password',
  'Speech to text': 'Voce in testo',
  'Language spoken': 'Lingua parlata',
  'Find out by listening': 'Scopri ascoltando',
  'Record and write down': 'Registra e annota',
  'Use the text': 'Usa il testo',
  'Writing down speech needs a model on this device (about {size} MB). It works without the internet, and nothing you say leaves the device.': 'Trascrivere il parlato richiede un modello su questo dispositivo (circa {size} MB). Funziona senza internet, e nulla di ciò che dici lascia il dispositivo.',
  'New plan': 'Nuovo piano',
  'Say when the exam is. The app works backwards from that day and puts a short session on each day of the calendar, and changes the sessions every day for what you got right.': 'Di’ quando è l’esame. L’app conta all’indietro da quel giorno e mette una sessione breve in ogni giorno del calendario, e cambia le sessioni ogni giorno in base a ciò che hai indovinato.',
  'The exam is today': 'L’esame è oggi',
  '{n} day left: the exam is on {day}': 'Manca {n} giorno: l’esame è il {day}',
  '{n} days left: the exam is on {day}': 'Mancano {n} giorni: l’esame è il {day}',
  'No session today': 'Nessuna sessione oggi',
  '{n} new card does not fit in the time: more minutes a day would help': '{n} nuova scheda non entra nel tempo: più minuti al giorno aiuterebbero',
  '{n} new cards do not fit in the time: more minutes a day would help': '{n} nuove schede non entrano nel tempo: più minuti al giorno aiuterebbero',
  'Delete the plan and its sessions that are still to come': 'Elimina il piano e le sue sessioni ancora da venire',
  'New plan for an exam': 'Nuovo piano per un esame',
  'What is the exam?': 'Qual è l’esame?',
  'Biology': 'Biologia',
  'Exam on': 'Esame il',
  'Which cards': 'Quali schede',
  'All my cards': 'Tutte le mie schede',
  '{n} minute a day': '{n} minuto al giorno',
  '{n} minutes a day': '{n} minuti al giorno',
  'No session on': 'Nessuna sessione il',
  'Make the plan': 'Crea il piano',
  'Synced': 'Sincronizzato',
  'Looking for your other devices. They have to be looking too: press "Sync now" there, or turn on the automatic sync.': 'Ricerca degli altri dispositivi. Anche loro devono cercare: premi «Sincronizza ora» lì, oppure attiva la sincronizzazione automatica.',
  'Better': 'Migliore',
  'Faster': 'Più veloce',
  'Models opened so far': 'Modelli aperti finora',
  'This browser gives the page no graphics card (WebGPU): models run on the processor. WebGPU needs https or localhost, and a browser that has it switched on (chrome://gpu shows why not).': 'Questo browser non dà alla pagina alcuna scheda grafica (WebGPU): i modelli girano sul processore. WebGPU richiede https o localhost, e un browser che lo abbia attivato (chrome://gpu mostra perché no).',
  'Timing…': 'Misurazione…',
  'Time the handwriting reader': 'Misura il lettore di scrittura a mano',
  'Size of the model': 'Dimensione del modello',
  'Exact ({mb} MB)': 'Esatto ({mb} MB)',
  'Compact ({mb} MB)': 'Compatto ({mb} MB)',
  'Compact is a third smaller and reads about two points less exactly. In a browser it is the one the graphics card can run (WebGPU), and much faster there. Changing it downloads the other file.': 'Il compatto è un terzo più piccolo e legge circa due punti in meno con precisione. In un browser è quello che la scheda grafica può far girare (WebGPU), e molto più veloce. Cambiarlo scarica l’altro file.',
  'Run models on': 'Esegui i modelli su',
  'Looking for an accelerator…': 'Ricerca di un acceleratore…',
  'Available on this device: {names}': 'Disponibile su questo dispositivo: {names}',
  'This device has no accelerator the app can use: models always run on the processor.': 'Questo dispositivo non ha un acceleratore utilizzabile dall’app: i modelli girano sempre sul processore.',
  'Accelerator when available': 'Acceleratore quando disponibile',
  'Processor only': 'Solo processore',
  'Graphics card ({mb} MB)': 'Scheda grafica ({mb} MB)',
  'Small ({mb} MB)': 'Piccolo ({mb} MB)',
  'Full ({mb} MB)': 'Completo ({mb} MB)',
  'Check the accelerator with a small test model': 'Verifica l’acceleratore con un piccolo modello di prova',
  'Checking…': 'Verifica…',
  'Not available in the browser.': 'Non disponibile nel browser.',
  'Opened on': 'Aperto su',
  'Failed': 'Non riuscito',
  'differs from the processor by at most {n}': 'differisce dal processore di al massimo {n}',
  'preparing the model for {name} (can take minutes)': 'preparazione del modello per {name} (può richiedere minuti)',
  'preparing the model': 'preparazione del modello',
  'Graphics card is the encoder in 16 bits, for a graphics card runtime (AMD\'s cannot run the 8-bit one): twice the size, much quicker there, reads about as well. Changing it downloads the encoder. Full is the published encoder unchanged, in 32 bits: the largest, reads like the original, and the form a phone\'s accelerator can take most of.': 'La scheda grafica è l’encoder a 16 bit, per un runtime di scheda grafica (quello di AMD non può eseguire la versione a 8 bit): il doppio di dimensione, molto più veloce lì, legge quasi allo stesso modo. Cambiarlo scarica l’encoder. Completo è l’encoder pubblicato invariato, a 32 bit: il più grande, legge come l’originale, ed è la forma che un acceleratore di telefono accetta più spesso.',
  'Graphics card is for a graphics card runtime (AMD\'s cannot run the quantised ones): not shrunk, reads like Exact.': 'La scheda grafica è per un runtime di scheda grafica (quello di AMD non può eseguire quelli quantizzati): non ridotto, legge come Esatto.',
  'Preparing…': 'Preparazione…',
  'Plans can only be made for the "Graphics card" size of the handwriting or the formula model (see their settings), once it is installed.': 'I piani si possono fare solo per la dimensione «Scheda grafica» del modello di scrittura a mano o di formule (vedi le loro impostazioni), una volta installata.',
  'Plan for the graphics card': 'Piano per la scheda grafica',
  'Precompile the formula plan': 'Precompila il piano delle formule',
  'Done: the plan is made and kept.': 'Fatto: il piano è creato e conservato.',
  'Formula pictures are always the same size, so there is nothing to pad and one plan to make. The graphics card works it out once (about 2 minutes) and keeps it; until then the first formula can wait.': 'Le immagini delle formule hanno sempre la stessa dimensione, quindi non c’è nulla da riempire e un solo piano da fare. La scheda grafica lo calcola una volta (circa 2 minuti) e lo conserva; nel frattempo la prima formula può attendere.',
  'Precompile picture sizes': 'Precompila le dimensioni delle immagini',
  'Handwriting: all {all} picture sizes of this quality have their plan.': 'Scrittura a mano: tutte le {all} dimensioni d’immagine di questa qualità hanno il loro piano.',
  'Formulas: the plan is made.': 'Formule: il piano è fatto.',
  'Formulas: no plan yet.': 'Formule: nessun piano ancora.',
  'Waiting for the block that is being read in the background...': 'In attesa del blocco in lettura in background...',
  'handwriting': 'scrittura a mano',
  'formulas': 'formule',
  'speech': 'voce',
  'search': 'ricerca',
  'embedding model': 'modello di embedding',
  'language model': 'modello linguistico',
  'picture part': 'parte immagine',
  'text part': 'parte testo',
  'sound part': 'parte audio',
  '{model} ({purpose}): {file}': '{model} ({purpose}): {file}',
  '{model} ({purpose}), {part}: {file}': '{model} ({purpose}), {part}: {file}',
  'processor (CPU)': 'processore (CPU)',
  'processor (in the browser)': 'processore (nel browser)',
  'graphics card ({name})': 'scheda grafica ({name})',
  'accelerator ({name})': 'acceleratore ({name})',
  'processor ({name})': 'processore ({name})',
  'graphics card making a plan': 'scheda grafica che crea un piano',
  'graphics card': 'scheda grafica',
  'accelerator': 'acceleratore',
  'processor': 'processore',
  'Size {done} of {total} done. Each takes 4 to 5 minutes; the app can be used meanwhile, and what is done is kept.': 'Dimensione {done} di {total} fatta. Ognuna richiede da 4 a 5 minuti; l’app si può usare nel frattempo, e ciò che è fatto viene conservato.',
  'Makes the graphics card\'s plan for every picture size of the handwriting reader now, for the quality chosen (about an hour the first time, once; another quality needs its own), so that no reading has to wait for one. Needs the "Graphics card" size of the handwriting model.': 'Crea ora il piano della scheda grafica per ogni dimensione d’immagine del lettore di scrittura, per la qualità scelta (circa un’ora la prima volta, una sola volta; un’altra qualità ha bisogno del suo), così nessuna lettura deve attendere. Richiede la dimensione «Scheda grafica» del modello di scrittura a mano.',
  'Pad to fixed sizes': 'Riempi fino a dimensioni fisse',
  'Applies to models opened from now on; restart the app to switch all of them. Models that write text word by word always use the processor.': 'Vale per i modelli aperti da ora in poi; riavvia l’app per cambiarli tutti. I modelli che scrivono il testo parola per parola usano sempre il processore.',
  'Graphics card runtime': 'Runtime della scheda grafica',
  'Running now: {name} (ONNX Runtime {version})': 'In uso ora: {name} (ONNX Runtime {version})',
  'the one in the app (processor only)': 'quello dell’app (solo processore)',
  'The one in the app (processor only)': 'Quello dell’app (solo processore)',
  'The chosen runtime could not be opened: {why}': 'Impossibile aprire il runtime scelto: {why}',
  'No runtime with graphics card support found. Put one in this folder (see docs/gpu-runtime-packs.md): {folder}': 'Nessun runtime con supporto alla scheda grafica trovato. Mettine uno in questa cartella (vedi docs/gpu-runtime-packs.md): {folder}',
  'Takes effect when the app is started again. Folder of the runtimes: {folder}': 'Ha effetto al prossimo avvio dell’app. Cartella dei runtime: {folder}',
  'High refresh rate': 'Alta frequenza di aggiornamento',
  'Asks the screen for the fastest refresh rate it has (90 or 120 Hz on some devices): scrolling and drawing look smoother, and the battery lasts less. Android may still slow it down, for example in battery saver.': 'Chiede allo schermo la sua frequenza di aggiornamento più alta (90 o 120 Hz su alcuni dispositivi): lo scorrimento e il disegno sono più fluidi, e la batteria dura meno. Android può comunque rallentarla, per esempio con il risparmio energetico.',
  'Turn it off when the battery is below': 'Disattivala quando la batteria è sotto',
  'Never': 'Mai',
  '{n} %': '{n} %',
  'Truth table': 'Tabella di verità',
  'Type a formula: p -> q, !p | q, (p and q) or not r, or in LaTeX. Put = between two formulas to see whether they are the same.': 'Scrivi una formula: p -> q, !p | q, (p e q) o non r, oppure in LaTeX. Metti = tra due formule per vedere se sono uguali.',
  'I cannot read that as a formula. Use single letters for the statements.': 'Non riesco a leggerlo come formula. Usa lettere singole per le proposizioni.',
  'That has too many letters (at most 10).': 'Ci sono troppe lettere (al massimo 10).',
  '0 first': 'Prima 0',
  '1 first': 'Prima 1',
  'Copy as Markdown': 'Copia come Markdown',
  'Copy as LaTeX': 'Copia come LaTeX',
  'Put on the page': 'Metti sulla pagina',
  'Copied': 'Copiato',
  'Always true (a tautology)': 'Sempre vera (una tautologia)',
  'Never true (a contradiction)': 'Mai vera (una contraddizione)',
  'Sometimes true': 'A volte vera',
  'The same in every row': 'Uguale in ogni riga',
  'Not the same: they differ in {n} of {total} rows': 'Non uguali: differiscono in {n} righe su {total}',
  'The second follows from the first': 'La seconda segue dalla prima',
  'The second does not follow from the first': 'La seconda non segue dalla prima',
  'Other forms of the formula': 'Altre forme della formula',
  'Of the first formula': 'Della prima formula',
  'True in rows': 'Vera nelle righe',
  'False in rows': 'Falsa nelle righe',
  'Shortest sum of products': 'Somma di prodotti più breve',
  'Shortest product of sums': 'Prodotto di somme più breve',
  'Every true row as a product': 'Ogni riga vera come prodotto',
  'Every false row as a sum': 'Ogni riga falsa come somma',
  'none': 'nessuna',
  'none (it is never true)': 'nessuna (non è mai vera)',
  'none (it is always true)': 'nessuna (è sempre vera)',
  'Make the truth table of a formula': 'Crea la tabella di verità di una formula',
  'Outline or flowchart': 'Schema o diagramma di flusso',
  'Automaton': 'Automa',
  'Tree': 'Albero',
  'Show an example': 'Mostra un esempio',
  'One line for each arrow: q0 -a-> q1 (q0 --a,b--> q1 for two symbols, -eps-> for the empty word). Say where it starts and which states accept: start: q0, accept: q2 (or >q0 and *q2).': 'Una riga per ogni freccia: q0 -a-> q1 (q0 --a,b--> q1 per due simboli, -eps-> per la parola vuota). Indica dove inizia e quali stati accettano: start: q0, accept: q2 (oppure >q0 e *q2).',
  'Brackets: A(B(D,E),C), a gap for a missing child: 8(3,10(,14). Or numbers put into a search tree, bst: 8 3 10 1 (also avl:, minheap:, maxheap:, array: 1 3 2 4). Lines after that: insert 7, delete 3.': 'Parentesi: A(B(D,E),C), un buco per un figlio mancante: 8(3,10(,14). Oppure numeri inseriti in un albero di ricerca, bst: 8 3 10 1 (anche avl:, minheap:, maxheap:, array: 1 3 2 4). Righe successive: insert 7, delete 3.',
  'One line for each edge: A - B, an arrow A -> B, a weight A -3- B (or A - B : 3), a chain A - B - C. A node on its own gets a line of its own. start: A says where the searches begin.': 'Una riga per ogni arco: A - B, una freccia A -> B, un peso A -3- B (o A - B : 3), una catena A - B - C. Un nodo da solo ha una riga propria. start: A indica da dove partono le ricerche.',
  'Show the balance factors': 'Mostra i fattori di bilanciamento',
  'Line {n} is not understood: {text}': 'La riga {n} non è compresa: {text}',
  'Try a word': 'Prova una parola',
  'accepted': 'accettata',
  'rejected': 'rifiutata',
  'stuck after {n} symbols': 'bloccato dopo {n} simboli',
