  'NFA with ε moves': 'NFA con mosse ε',
  'no (a missing arrow is a dead end)': 'no (una freccia mancante è un vicolo cieco)',
  'none (there is a cycle)': 'nessuno (c’è un ciclo)',
  'not for negative weights': 'non per pesi negativi',
  'no start state (write start: q0 or >q0)': 'nessuno stato iniziale (scrivi start: q0 o >q0)',
  'no accepting state (write accept: q1 or *q1)': 'nessuno stato di accettazione (scrivi accept: q1 o *q1)',
  'a bracket is not closed': 'una parentesi non è chiusa',
  'a node has no name before "("': 'un nodo non ha un nome prima di «(»',
  'the first place is the root, it cannot be a hole': 'il primo posto è la radice, non può essere un buco',
  'Connect temporarily': 'Connetti temporaneamente',
  'Fetching the note from your other device...': 'Recupero della nota dall’altro dispositivo...',
  'The note could not be fetched. Is the device that has it online?': 'Non è stato possibile recuperare la nota. Il dispositivo che la ha è online?',
  'Scan the code of the web version': 'Scansiona il codice della versione web',
  'On a computer that is not yours: "Connect temporarily" shows a code that you scan with your phone. Your notes are listed here, and each one comes when you open it. This browser forgets them again when the tab is closed.': 'Su un computer che non è il tuo: «Connetti temporaneamente» mostra un codice che scansioni con il telefono. Le tue note sono elencate qui, e ciascuna arriva quando la apri. Questo browser le dimentica di nuovo alla chiusura della scheda.',
  'This browser is connected temporarily. There are changes that no other device has yet: they are lost if you close the tab before the next sync.': 'Questo browser è connesso temporaneamente. Ci sono modifiche che nessun altro dispositivo ha ancora: vanno perse se chiudi la scheda prima della prossima sincronizzazione.',
  'This browser is connected temporarily. Everything here is on your other devices; it is forgotten when you sign out or close the tab.': 'Questo browser è connesso temporaneamente. Tutto ciò che è qui si trova sugli altri dispositivi; viene dimenticato quando esci o chiudi la scheda.',
  'Sign out and forget everything here': 'Esci e dimentica tutto qui',
  'Sign out of this browser?': 'Uscire da questo browser?',
  'This browser forgets the notes and the profile. No other device is connected, so notes that are only here are lost.': 'Questo browser dimentica le note e il profilo. Nessun altro dispositivo è connesso, quindi le note che sono solo qui andranno perse.',
  'There are changes here that no other device has yet. They are lost when you sign out. Press "Sync now" first and wait until it is done to keep them. This browser forgets the notes and the profile either way.': 'Ci sono modifiche qui che nessun altro dispositivo ha ancora. Vanno perse all’uscita. Premi prima «Sincronizza ora» e attendi che finisca per conservarle. Questo browser dimentica comunque le note e il profilo.',
  'This browser forgets the notes and the profile. Your other devices keep everything.': 'Questo browser dimentica le note e il profilo. I tuoi altri dispositivi conservano tutto.',
  'Scan this code with your phone: with the camera, or in Notation under Settings → Sync profile → "Scan the code of the web version".': 'Scansiona questo codice con il telefono: con la fotocamera, o in Notation sotto Impostazioni → Profilo di sincronizzazione → «Scansiona il codice della versione web».',
  'Waiting for your phone...': 'In attesa del telefono...',
  'This browser is signed in until you sign out or close the tab, and then forgets your notes. The code works for ten minutes and only once; your phone still asks you before it lets this browser in.': 'Questo browser resta connesso fino alla tua uscita o alla chiusura della scheda, e poi dimentica le note. Il codice funziona dieci minuti e una sola volta; il telefono chiede comunque il permesso prima di far entrare questo browser.',
  'Point the camera at the code that the web version shows.': 'Punta la fotocamera sul codice mostrato dalla versione web.',
  'temporary': 'temporaneo',
  'Sign in with your cloud folder': 'Accedi con la tua cartella cloud',
  'signed in with the recovery key': 'connesso con la chiave di recupero',
  'Your recovery key': 'La tua chiave di recupero',
  'Keep it in a password manager or write it on paper. It is shown only now and the app does not keep it. With this key and your cloud account you can sign in to your profile on a new device; without it, only a link from one of your devices works.': 'Conservala in un gestore di password o scrivila su carta. Viene mostrata solo ora e l’app non la conserva. Con questa chiave e il tuo account cloud puoi accedere al tuo profilo su un nuovo dispositivo; senza, funziona solo un link da uno dei tuoi dispositivi.',
  'I have saved the key': 'Ho salvato la chiave',
  'Use the folder your other devices sync through, and the recovery key that was shown when signing in was turned on there. Your notes, folders and settings come to this device.': 'Usa la cartella con cui sincronizzano gli altri dispositivi, e la chiave di recupero mostrata all’accesso è stata attivata lì. Le tue note, cartelle e impostazioni arrivano su questo dispositivo.',
  '{service} is connected.': '{service} è collegato.',
  'Connect your account first:': 'Collega prima il tuo account:',
  'In a browser, your Nextcloud has to allow this website to talk to it (CORS headers); the documentation says which.': 'In un browser, il tuo Nextcloud deve consentire a questo sito di parlarvi (intestazioni CORS); la documentazione dice quali.',
  'Recovery key': 'Chiave di recupero',
  '"Sign out" in the menu removes everything from this browser again.': '«Esci» nel menu rimuove di nuovo tutto da questo browser.',
  'Sign in': 'Accedi',
  'Sign in with this folder?': 'Accedere con questa cartella?',
  'Anyone who has the recovery key and can open this cloud folder will be able to sign in to your profile and read your notes, without anyone saying yes on one of your other devices. Your devices show each device that signs in this way, and you can take it out. The key is shown once and not kept by the app. Adding a device with a link works as before.': 'Chiunque abbia la chiave di recupero e possa aprire questa cartella cloud potrà accedere al tuo profilo e leggere le tue note, senza che nessuno dica sì su uno dei tuoi altri dispositivi. I tuoi dispositivi mostrano ogni dispositivo che entra in questo modo, e puoi toglierlo. La chiave viene mostrata una sola volta e l’app non la conserva. Aggiungere un dispositivo con un link funziona come prima.',
  'Turn on': 'Attiva',
  'Turn off signing in with the folder?': 'Disattivare l’accesso con la cartella?',
  'The sign-in file is taken out of the folder, so the recovery key stops working. Devices that are already in stay in.': 'Il file di accesso viene tolto dalla cartella, quindi la chiave di recupero smette di funzionare. I dispositivi già dentro restano.',
  'Turn off': 'Disattiva',
  'Make a new recovery key?': 'Creare una nuova chiave di recupero?',
  'The old key stops working at once. Devices that signed in with it stay in; to cut one off, take it out of the list of devices.': 'La vecchia chiave smette subito di funzionare. I dispositivi che sono entrati con essa restano; per escluderne uno, toglilo dall’elenco dei dispositivi.',
  'Make a new key': 'Crea una nuova chiave',
  'Let me sign in with this folder': 'Consenti l’accesso con questa cartella',
  'On a new device or in a browser, sign in with this cloud account and a recovery key instead of a link and a yes on another device. Off by default: adding a device with a link stays the careful way.': 'Su un nuovo dispositivo o in un browser, accedi con questo account cloud e una chiave di recupero invece che con un link e un sì su un altro dispositivo. Disattivato di default: aggiungere un dispositivo con un link resta il modo prudente.',
  'Needs the sync through the folder to be on, with the account connected on this device.': 'Richiede che la sincronizzazione tramite cartella sia attiva, con l’account collegato su questo dispositivo.',
  'Make a new recovery key': 'Crea una nuova chiave di recupero',
  'Signed in with the recovery key: {devices}': 'Accesso con la chiave di recupero: {devices}',
  'This device is part of a profile already. Leave it first to sign in to another.': 'Questo dispositivo fa già parte di un profilo. Esci prima per accedere a un altro.',
  'Connect the account of {service} first.': 'Collega prima l’account di {service}.',
  'That recovery key does not open this folder. Check it for typing mistakes, and that it is the latest one if you made a new key.': 'Quella chiave di recupero non apre questa cartella. Controllala per errori di battitura, e che sia l’ultima se hai creato una nuova chiave.',
  'The sign-in file in the folder cannot be read.': 'Il file di accesso nella cartella non si può leggere.',
  'The sign-in file in the folder is from a newer version of the app: update the app.': 'Il file di accesso nella cartella è di una versione più recente dell’app: aggiorna l’app.',
  'Signing in needs the sync through a cloud folder to be on, with the account connected on this device.': 'L’accesso richiede che la sincronizzazione tramite cartella cloud sia attiva, con l’account collegato su questo dispositivo.',
  'Signing in is not on.': 'L’accesso non è attivo.',
  'That is not a recovery key. It has 25 letters and digits, like ABCDE-FGHJK-MNPQR-STUVW-XY234.': 'Non è una chiave di recupero. Ha 25 lettere e cifre, come ABCDE-FGHJK-MNPQR-STUVW-XY234.',
  'Nothing to sign in to was found in this folder. Is signing in turned on on your other device, and is the folder name the same?': 'Non è stato trovato nulla a cui accedere in questa cartella. L’accesso è attivo sull’altro dispositivo, e il nome della cartella è lo stesso?',
  'Enter the address of your Nextcloud first.': 'Inserisci prima l’indirizzo del tuo Nextcloud.',
  'Waiting for you to approve in the browser...': 'In attesa della tua approvazione nel browser...',
  'Log in with the browser': 'Accedi con il browser',
  'The browser could not be opened. Open this address yourself:': 'Impossibile aprire il browser. Apri tu questo indirizzo:',
  'Or enter an app password yourself:': 'Oppure inserisci tu una password dell’app:',
  'That is not a server address.': 'Non è un indirizzo di server.',
  'This server did not start a login. Is it a Nextcloud (version 16 or newer), and is the address right?': 'Questo server non ha avviato un accesso. È un Nextcloud (versione 16 o successiva), e l’indirizzo è giusto?',
  'The server did not hand over a login.': 'Il server non ha fornito un accesso.',
  'The login was not approved in time. Try again.': 'L’accesso non è stato approvato in tempo. Riprova.',
  'The server could not be reached: {error}': 'Impossibile raggiungere il server: {error}',
  'The password of the Nextcloud account is not in the keystore of this device. Log in again in the settings under Sync and sharing.': 'La password dell’account Nextcloud non è nel portachiavi di questo dispositivo. Accedi di nuovo nelle impostazioni, sotto Sincronizzazione e condivisione.',
  'The password of this account is not in the keystore of this device. Log in again.': 'La password di questo account non è nel portachiavi di questo dispositivo. Accedi di nuovo.',
  'Choose calendars': 'Scegli i calendari',
  'The system keystore did not keep the password, so the account was not saved. Is the keyring unlocked?': 'Il portachiavi del sistema non ha conservato la password, quindi l’account non è stato salvato. Il portachiavi è sbloccato?',
  'Eyedropper': 'Contagocce',
  'Pick a color from anything on the page (a drawing, a picture, a PDF) for the pen: tap the button or press I, then touch the color.': 'Prendi un colore da qualsiasi cosa nella pagina (un disegno, un’immagine, un PDF) per la penna: tocca il pulsante o premi I, poi tocca il colore.',
  'Eyedropper: touch anything on the page to draw in its color (I)': 'Contagocce: tocca qualsiasi cosa nella pagina per disegnare con il suo colore (I)',
  'Free transform': 'Trasformazione libera',
  'Bend selected drawings: distort them by the corners, give them perspective, skew them, turn them by any angle or warp them with a net. The whole change is one step to take back.': 'Deforma i disegni selezionati: trascinali dagli angoli, dai loro una prospettiva, inclinali, ruotali di un angolo qualsiasi o deformali con una griglia. Tutta la modifica è un solo passo da annullare.',
  'Transform: distort, perspective, skew, rotate, warp': 'Trasforma: deforma, prospettiva, inclina, ruota, curva',
  'Distort: pull the corners anywhere': 'Deforma: trascina gli angoli ovunque',
  'Perspective: pull a corner, the next one follows': 'Prospettiva: trascina un angolo, il successivo lo segue',
  'Skew: slide the edges': 'Inclina: fai scorrere i bordi',
  'Rotate (Shift: in steps of 15°)': 'Ruota (Maiusc: a passi di 15°)',
  'Warp: bend the drawing with a net': 'Curva: piega il disegno con una griglia',
  'Start again': 'Ricomincia',
  'Fill bucket': 'Secchiello di riempimento',
  'Fill a closed area of a drawing with the pen color by touching it: the area is found from the lines round it, and small gaps in them can be closed. The fill is a shape under the lines, so it can be recolored or moved later.': 'Riempi un’area chiusa di un disegno con il colore della penna toccandola: l’area viene trovata dalle linee intorno, e piccoli buchi in esse possono essere chiusi. Il riempimento è una forma sotto le linee, quindi può essere ricolorato o spostato più tardi.',
  'Fill bucket: touch a closed area to fill it with the pen color (G)': 'Secchiello: tocca un’area chiusa per riempirla con il colore della penna (G)',
  'Gap closing: how big a gap in the lines still closes an area': 'Chiusura dei buchi: quanto può essere grande un buco nelle linee e chiudere ancora un’area',
  'No gap closing': 'Nessuna chiusura dei buchi',
  'Small gaps': 'Buchi piccoli',
  'Medium gaps': 'Buchi medi',
  'Large gaps': 'Buchi grandi',
  'There are no lines to close an area yet: draw the outline first.': 'Non ci sono ancora linee che chiudano un’area: disegna prima il contorno.',
  'That area is not closed. Close the lines, or turn gap closing up (the button beside the bucket).': 'Quell’area non è chiusa. Chiudi le linee, o alza la chiusura dei buchi (il pulsante accanto al secchiello).',
  'That is on a line: touch the area beside it.': 'Quello è su una linea: tocca l’area accanto.',
  'Turn the canvas left': 'Ruota la tela a sinistra',
  'Turn the canvas right': 'Ruota la tela a destra',
  'Put the canvas straight': 'Raddrizza la tela',
  'The canvas is turned: tap to put it straight': 'La tela è ruotata: tocca per raddrizzarla',
  'Bring your notes from another app': 'Porta le tue note da un’altra app',
  'Obsidian: a vault folder': 'Obsidian: una cartella vault',
  'Notes, folders, pictures, PDFs and tags are taken; links between notes keep working.': 'Vengono prese note, cartelle, immagini, PDF ed etichette; i collegamenti tra le note continuano a funzionare.',
  'Obsidian: a vault as a zip': 'Obsidian: un vault in zip',
  'The same, from a zip of the vault folder.': 'Lo stesso, da uno zip della cartella del vault.',
  'Notion: an export': 'Notion: un’esportazione',
  'In Notion: Settings, Export all workspace content, Markdown & CSV. Pick the zip you get.': 'In Notion: Impostazioni, Esporta tutti i contenuti dello spazio di lavoro, Markdown e CSV. Scegli lo zip che ottieni.',
  'GoodNotes: PDFs or a .goodnotes file': 'GoodNotes: PDF o un file .goodnotes',
  'In GoodNotes: Share, Export as PDF. Handwriting stays as it looks. A .goodnotes file can only give its PDFs.': 'In GoodNotes: Condividi, Esporta come PDF. La scrittura a mano resta com’è appare. Un file .goodnotes può dare solo i suoi PDF.',
  'Reading your notes...': 'Lettura delle tue note...',
  'Pick the vault folder': 'Scegli la cartella del vault',
  'Pick the Notion export (zip)': 'Scegli l’esportazione di Notion (zip)',
  'Pick the vault (zip)': 'Scegli il vault (zip)',
  'Pick the PDFs or the .goodnotes files': 'Scegli i PDF o i file .goodnotes',
  'What is written by hand in "{name}" is in a format that cannot be read. Only its PDF pages were taken; to keep the handwriting, export the notebook as a PDF in GoodNotes.': 'La scrittura a mano in «{name}» è in un formato che non si può leggere. Sono state prese solo le sue pagine PDF; per conservare la scrittura, esporta il quaderno in PDF da GoodNotes.',
  'Could not read the notes: {error}': 'Impossibile leggere le note: {error}',
  'Nothing was taken in': 'Non è stato importato nulla',
  'Your notes are here': 'Le tue note sono qui',
  '{n} PDF': '{n} PDF',
  '{n} PDFs': '{n} PDF',
  '{n} table (a database)': '{n} tabella (un database)',
  '{n} tables (databases)': '{n} tabelle (database)',
  '{n} picture': '{n} immagine',
  '{n} folder': '{n} cartella',
