  '{n} links between notes kept': '{n} collegamenti tra note conservati',
  'Could not be read': 'Non è stato possibile leggerlo',
  'Left out (not notes or pictures)': 'Lasciato fuori (non note né immagini)',
  'Links to something that was not there (kept as plain text)': 'Collegamenti a qualcosa che non c’era (conservati come testo semplice)',
  'Open a note': 'Apri una nota',
  'This is not a zip file.': 'Questo non è un file zip.',
  'This is not a GoodNotes file. In GoodNotes, choose Share → Export as PDF and open that PDF here.': 'Questo non è un file GoodNotes. In GoodNotes scegli Condividi → Esporta come PDF, e apri qui quel PDF.',
  'There is no PDF in this GoodNotes file, and what is written in it cannot be read. In GoodNotes, choose Share → Export as PDF and open that PDF here.': 'In questo file GoodNotes non c’è alcun PDF, e ciò che vi è scritto non può essere letto. In GoodNotes scegli Condividi → Esporta come PDF, e apri qui quel PDF.',
  'The archive has too many files.': 'L’archivio contiene troppi file.',
  'A file in the archive is too big.': 'Un file nell’archivio è troppo grande.',
  'The archive is too big.': 'L’archivio è troppo grande.',
  'A to-do line is found in a note': 'Una riga da fare viene trovata in una nota',
