  'Something is kept from the web or shared to the app': 'Qualcosa viene conservato dal web o condiviso con l’app',
  'You press a trigger (a shortcut or the pen button)': 'Premi un innesco (una scorciatoia o il pulsante della penna)',
  'how many pages the note has now': 'quante pagine ha ora la nota',
  'how many highlights were added': 'quanti evidenziatori sono stati aggiunti',
