  'the day the task was due': 'il giorno in cui l’attività era in scadenza',
  'the number of the trigger': 'il numero dell’innesco',
  'note, clip, page, pdf or picture': 'nota, ritaglio, pagina, pdf o immagine',
  'the address it came from': 'l’indirizzo da cui proviene',
  'the name of the site': 'il nome del sito',
  'the time the meeting started': 'l’ora in cui è iniziata la riunione',
  'the day of the meeting': 'il giorno della riunione',
  'the time it starts': 'l’ora in cui inizia',
  'the day it starts': 'il giorno in cui inizia',
  'what is to be done': 'cosa c’è da fare',
  'the whole line': 'la riga intera',
  'the day it is due': 'il giorno in cui è in scadenza',
  'the line without the date': 'la riga senza la data',
  'its time': 'la sua ora',
  'the date': 'la data',
  'Add text to a note (or to a daily note)': 'Aggiungi testo a una nota (o a una nota giornaliera)',
  'Give the note a tag': 'Assegna un’etichetta alla nota',
  'Star the note (it is listed as a favourite on the dashboard)': 'Metti la nota tra i preferiti (compare tra i preferiti nel pannello)',
  'Add a translation of the note as a text box (the assistant writes it)': 'Aggiungi una traduzione della nota come casella di testo (la scrive l’assistente)',
  'Add a summary of the note as a text box (the assistant writes it)': 'Aggiungi un riassunto della nota come casella di testo (lo scrive l’assistente)',
  'Add an outline of the note as a text box (the assistant writes it)': 'Aggiungi uno schema della nota come casella di testo (lo scrive l’assistente)',
  'Make a new note from a template': 'Crea una nuova nota da un modello',
  'Prepare a note for the meeting (with what was left open last time)': 'Prepara una nota per la riunione (con ciò che era rimasto aperto l’altra volta)',
  'Set a reminder': 'Imposta un promemoria',
  'Save the pages of the note as pictures (PNG) into a folder': 'Salva le pagine della nota come immagini (PNG) in una cartella',
  'Add the web page it came from to the sources (citations)': 'Aggiungi la pagina web da cui proviene alle fonti (citazioni)',
  'Ask me what to do about the note (a card on the dashboard)': 'Chiedimi cosa fare della nota (una scheda nel pannello)',
  'Give a note without a title one, from what it says': 'Dai un titolo a una nota senza titolo, da ciò che dice',
  'Make flashcards from the note (the assistant writes them)': 'Crea schede di studio dalla nota (le scrive l’assistente)',
  'Add a task when flashcards are due for review': 'Aggiungi un’attività quando ci sono schede da ripassare',
  'Add it to': 'Aggiungilo a',
  'The note the rule is about': 'La nota a cui si riferisce la regola',
  'A daily note (made if it is not there)': 'Una nota giornaliera (creata se non c’è)',
  'Title of the daily note': 'Titolo della nota giornaliera',
  'Folder for a new daily note': 'Cartella per una nuova nota giornaliera',
  'Text to add': 'Testo da aggiungere',
  'It goes in a box under the rest of the last page': 'Va in una casella sotto il resto dell’ultima pagina',
  'Tag': 'Etichetta',
  'A tag of the tag tree, e.g. school/maths; the words in braces of the event can be used: reading/{kind}': 'Un’etichetta dell’albero delle etichette, ad es. scuola/mate; si possono usare le parole tra parentesi graffe dell’evento: lettura/{kind}',
  'Title of the note': 'Titolo della nota',
  '{title} is the title of the event; {date} today': '{title} è il titolo dell’evento; {date} la data di oggi',
  'Template (optional)': 'Modello (facoltativo)',
  '{title} is the name of the event, {day} its day, {start} its time': '{title} è il nome dell’evento, {day} il suo giorno, {start} la sua ora',
  'Bring along what is still open from the last meeting': 'Riporta ciò che è rimasto aperto dall’ultima riunione',
  'Yes: the to-do lines of the last note of that name': 'Sì: le righe da fare dell’ultima nota con quel nome',
  'This evening (18:00)': 'Questa sera (18:00)',
  'Tomorrow morning (9:00)': 'Domani mattina (9:00)',
  'In a week (9:00)': 'Tra una settimana (9:00)',
  'Save the pictures in this folder': 'Salva le immagini in questa cartella',
  'the note\'s': 'della nota',
  '{title} is empty, {date} today\'s date': '{title} è vuoto, {date} la data di oggi',
  '{title} is the event\'s title, {date} today\'s date': '{title} è il titolo dell’evento, {date} la data di oggi',
  '{summary} is what is to be done, {line} the whole line, {title} the note\'s title. The task is on the day the line says ("by Friday"), else on the day below': '{summary} è ciò che va fatto, {line} la riga intera, {title} il titolo della nota. L’attività va nel giorno che dice la riga («entro venerdì»), altrimenti nel giorno sotto',
  'The page the note was made from (its address, its title, the site and the day it was kept) is added to the sources of the citations, to cite in any note with [@key]. A page that is a source already is not added again.': 'La pagina da cui è nata la nota (il suo indirizzo, il titolo, il sito e il giorno in cui è stata conservata) viene aggiunta alle fonti delle citazioni, da citare in qualsiasi nota con [@chiave]. Una pagina che è già una fonte non viene aggiunta di nuovo.',
  'The note is listed on the dashboard: "Still relevant?" with the answers: keep it, archive it, remind me in a week, make flashcards of it, or not now. Nothing changes until you answer.': 'La nota compare nel pannello: «Ancora rilevante?» con le risposte: tienila, archiviala, ricordamelo tra una settimana, falle schede di studio, o non ora. Non cambia nulla finché non rispondi.',
  'The note is starred, so that it is listed as a favourite on the dashboard.': 'La nota riceve una stella, così compare tra i preferiti nel pannello.',
  'The assistant reads the text of the note and writes its outline (topics and points) into a text box under the rest of the last page. A later run replaces it. Needs the assistant.': 'L’assistente legge il testo della nota e scrive il suo schema (temi e punti) in una casella di testo sotto il resto dell’ultima pagina. Un’esecuzione successiva lo sostituisce. Richiede l’assistente.',
  'The assistant reads the text of the note and writes a short summary into a text box under the rest of the last page. A later run replaces it. Needs the assistant.': 'L’assistente legge il testo della nota e scrive un breve riassunto in una casella di testo sotto il resto dell’ultima pagina. Un’esecuzione successiva lo sostituisce. Richiede l’assistente.',
