  'Often': 'Spesso',
  'When the model is unsure of a formula, it reads it again with a thinner and a thicker pen and keeps the surest reading. Normal does this for about one formula in ten and reads about 2 points more right; Often is about three in ten; Never is the quickest.': 'Quando il modello non è sicuro di una formula, la rilegge con una penna più sottile e una più spessa, e tiene la lettura più sicura. Normale lo fa per circa una formula su dieci e legge circa 2 punti in più correttamente; Spesso, circa tre su dieci; Mai è il più veloce.',
  'The reader was not sure of this word': 'Il lettore non era sicuro di questa parola',
