  'What is in the way': 'Cosa si mette in mezzo',
  '**Who wants what, and what is in the way:**': '**Chi vuole cosa, e cosa si mette in mezzo:**',
  '## Scenes still to write': '## Scene ancora da scrivere',
  '**Chords:**': '**Accordi:**',
  'Copy formatting, then select text and press again to apply it': 'Copia la formattazione, poi seleziona il testo e premi di nuovo per applicarla',
  'A title, an introduction, the main part and a conclusion, the sources at the end': 'Un titolo, un’introduzione, la parte principale e una conclusione, le fonti in fondo',
  'Every paragraph of a kind takes its look; what is picked for single words stays.': 'Ogni paragrafo di un tipo prende il suo aspetto; ciò che è scelto per le singole parole resta.',
  'Read from your drawing: {nodes} circles, {edges} lines. Check the names, then put it on the page; your drawing is replaced.': 'Letto dal tuo disegno: {nodes} cerchi, {edges} linee. Controlla i nomi, poi mettilo sulla pagina; il tuo disegno viene sostituito.',
  'This package was exported in the newest Anki format. Export it again with "Support older Anki versions" ticked.': 'Questo pacchetto è stato esportato nel formato Anki più recente. Esportalo di nuovo spuntando «Supporta le versioni più vecchie di Anki».',
  '{page} is the number of the page, {pages} how many there are, {title} the title of the note, {date} today.': '{page} è il numero della pagina, {pages} quante sono, {title} il titolo della nota, {date} la data di oggi.',
  'Remove this PDF?': 'Rimuovere questo PDF?',
  '"{name}" and its pages are taken out of the note, with what is drawn or written on them.': '«{name}» e le sue pagine vengono tolti dalla nota, con ciò che è disegnato o scritto su di esse.',
  'The PDFs of this note': 'I PDF di questa nota',
  '{n} pages': '{n} pagine',
  'Remove {name}…': 'Rimuovi {name}…',
  '{n} PDFs ({pages} Pages)': '{n} PDF ({pages} pagine)',
  'The pages of the PDFs in the file do not fit them; the note is opened without them': 'Le pagine dei PDF nel file non corrispondono a essi; la nota viene aperta senza di loro',
  'A PDF in the file does not match its checksum and was left out': 'Un PDF nel file non corrisponde al suo checksum ed è stato omesso',
  'You are on mobile data. These models are large: untick them to download later on Wi-Fi (the settings have the same list), or go ahead if your plan allows it.': 'Sei con i dati mobili. Questi modelli sono grandi: deselezionali per scaricarli più tardi con il Wi-Fi (le impostazioni hanno la stessa lista), oppure procedi se il tuo piano lo consente.',
  'Export the whole note as Markdown': 'Esporta l’intera nota come Markdown',
  'Export as Markdown': 'Esporta come Markdown',
  'Handwriting is in it as read by the app: check it. Drawings are not in it.': 'La scrittura a mano è inclusa come letta dall’app: controllala. I disegni non ci sono.',
  'Syncs by itself whenever two of your devices are online at the same time. This needs the signalling server: the device stays connected to it, which tells it that a device of yours is online (it cannot tell which, or what is in your notes). Off: only when you press "Sync now".': 'Si sincronizza da solo ogni volta che due dei tuoi dispositivi sono online nello stesso momento. Questo richiede il server di segnalazione: il dispositivo resta collegato ad esso, il che gli indica che un tuo dispositivo è online (non può sapere quale, né cosa c’è nelle tue note). Disattivato: solo quando premi «Sincronizza ora».',
  'For devices that are not online at the same time: each puts what changed in a folder on your cloud storage and takes in what the others put there, without the signalling server. Two things still need it: handing the cloud accounts to your other devices (when two of them sync directly; or connect the account on each device yourself), and working on one note on two devices at the same time.': 'Per i dispositivi che non sono online nello stesso momento: ciascuno deposita ciò che è cambiato in una cartella del tuo spazio cloud e riprende ciò che gli altri vi hanno depositato, senza il server di segnalazione. Due cose ne hanno ancora bisogno: passare gli account cloud agli altri dispositivi (quando due di essi si sincronizzano direttamente; oppure collegare tu l’account su ogni dispositivo), e lavorare su una stessa nota da due dispositivi contemporaneamente.',
  'A file in the folder is not sealed with the key of this profile; it was not taken.': 'Un file nella cartella non è sigillato con la chiave di questo profilo; non è stato preso.',
  'Your notes are also kept in sync through the cloud folder below, also when your devices are not online at the same time.': 'Le tue note vengono sincronizzate anche tramite la cartella cloud qui sotto, anche quando i tuoi dispositivi non sono online nello stesso momento.',
  'While a note is open, this device is connected to the signalling server and tells your other devices which notes are open; a note that is open on two of them is edited together live. What it tells them is encrypted: the server cannot see which note it is, nor that the same note is opened again. Off: the server hears nothing from this device while a note is open, and a note changed on two devices is brought together at the next sync.': 'Mentre una nota è aperta, questo dispositivo è collegato al server di segnalazione e gli comunica quali note sono aperte; una nota aperta su due tuoi dispositivi viene modificata insieme in tempo reale. Ciò che gli trasmette è cifrato: il server non può vedere di quale nota si tratta, né che la stessa nota viene riaperta. Disattivato: il server non sente nulla da questo dispositivo mentre una nota è aperta, e una nota modificata su due dispositivi viene unita alla sincronizzazione successiva.',
  'Handwriting: {done} of {all} picture sizes of this quality have their plan. Missing: {missing} (widths in columns of 28 pixels). Plans made before this was noted are found again by "Precompile picture sizes", in seconds each.': 'Scrittura a mano: {done} su {all} dimensioni d’immagine di questa qualità hanno il loro piano. Mancanti: {missing} (larghezze in colonne da 28 pixel). I piani fatti prima che questo fosse annotato vengono ritrovati da «Precompila le dimensioni delle immagini», in pochi secondi ciascuno.',
  'Models run on the processor now, so Exact is used: it reads the same there, as fast, with about 1 GB less memory. The graphics card file is kept for when the card is used again.': 'I modelli ora girano sul processore, quindi viene usato Esatto: legge allo stesso modo lì, altrettanto veloce, con circa 1 GB di memoria in meno. Il file della scheda grafica viene conservato per quando la scheda sarà di nuovo usata.',
  'the graphics card is making its plan for this picture size (minutes, once); the processor reads meanwhile': 'la scheda grafica sta creando il suo piano per questa dimensione d’immagine (minuti, una volta sola); nel frattempo il processore legge',
  'Always on with CoreML for the "Graphics card" size of the handwriting model: CoreML prepares it once for each picture width (seconds, kept for the next start), so pictures are made one of a few widths.': 'Sempre attivo con CoreML per la dimensione «Scheda grafica» del modello di scrittura a mano: CoreML lo prepara una volta per ogni larghezza d’immagine (secondi, conservato per il prossimo avvio), quindi le immagini vengono create in poche larghezze.',
  'Needed with this accelerator: it works out a plan for every picture size it sees, which takes minutes. Pictures of handwriting are made one of a few widths (about a fifth more work) so each plan is made once.': 'Necessario con questo acceleratore: calcola un piano per ogni dimensione d’immagine che vede, il che richiede minuti. Le immagini della scrittura vengono create in poche larghezze (circa un quinto di lavoro in più), così ogni piano viene fatto una sola volta.',
  'Makes pictures of handwriting one of a few widths, so an accelerator that works out a plan for each size (AMD) does it a few times, not for every line. Costs about a fifth more work; switch it off where the accelerator takes any size.': 'Fa sì che le immagini della scrittura abbiano una di poche larghezze, così un acceleratore che calcola un piano per ogni dimensione (AMD) lo fa poche volte, non per ogni riga. Costa circa un quinto di lavoro in più; disattivalo dove l’acceleratore accetta qualsiasi dimensione.',
  'Line and shape correction': 'Correzione di linee e forme',
  'How close to straight a line, or to a rectangle, ellipse, triangle or diamond a drawing, must be before it is corrected. Applies to notes opened after the change.': 'Quanto una linea deve essere dritta, o un disegno vicino a un rettangolo, un\'ellisse, un triangolo o un rombo, prima di essere corretto. Vale per le note aperte dopo la modifica.',
